1	"use client";
2	
3	import { useState, useEffect, useCallback } from "react";
4	import { useRouter, useParams } from "next/navigation";
5	import { useAuth } from "@/lib/auth-context";
6	import { Button } from "@/components/ui/button";
7	import { Input } from "@/components/ui/input";
8	import { Label } from "@/components/ui/label";
9	import { Textarea } from "@/components/ui/textarea";
10	import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
11	import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
12	import { ProtectedRoute } from "@/components/protected-route";
13	import Link from "next/link";
14	import { ArrowLeft, Edit, Users, Banknote, ChevronLeft, ChevronRight, Save, X, CheckCircle, AlertCircle, Loader2 } from "lucide-react";
15	import { Badge } from "@/components/ui/badge";
16	import { ApplicationStatus } from "@/src/types/application";
17	
18	interface Application {
19	  id: number;
20	  application_number: string;
21	  customer_id: number;
22	  customer: {
23	    id: number;
24	    name: string;
25	    mobile: string;
26	    email?: string;
27	    address?: string;
28	  };
29	  service_id: number;
30	  service: {
31	    id: number;
32	    name: string;
33	    description?: string;
34	    base_price: number;
35	    fields: ServiceField[];
36	  };
37	  status: ApplicationStatus;
38	  assigned_staff_id?: number | null;
39	  assigned_staff?: {
40	    id: number;
41	    full_name: string;
42	    email: string;
43	  } | null;
44	  application_data: Record<string, any>;
45	  notes?: string;
46	  created_at: string;
47	  updated_at: string;
48	}
49	
50	interface ServiceField {
51	  id: number;
52	  service_id: number;
53	  name: string;
54	  label: string;
55	  field_type: 'text' | 'number' | 'date' | 'select' | 'textarea' | 'boolean';
56	  is_required: boolean;
57	  options?: string[];
58	  help_text?: string;
59	  order: number;
60	}
61	
62	interface Staff {
63	  id: number;
64	  email: string;
65	  full_name: string;
66	  is_active: boolean;
67	  platform_role?: string;
68	}
69	
70	function ApplicationDetailContent() {
71	  const { user, loading: authLoading } = useAuth();
72	  const router = useRouter();
73	  const params = useParams();
74	  const applicationId = params?.id as string;
75	
76	  const [loading, setLoading] = useState(true);
77	  const [error, setError] = useState<string | null>(null);
78	  const [application, setApplication] = useState<Application | null>(null);
79	  const [staff, setStaff] = useState<Staff[]>([]);
80	  const [saving, setSaving] = useState(false);
81	  const [editMode, setEditMode] = useState(false);
82	
83	  // Form data for editing
84	  const [formData, setFormData] = useState({
85	    status: "" as ApplicationStatus | "",
86	    assigned_staff_id: "" as number | "",
87	    application_data: {} as Record<string, any>,
88	    notes: "",
89	  });
90	
91	  const shopIdParam = new URLSearchParams(window.location.search).get("shop_id");
92	  const [shopId, setShopId] = useState<number | null>(shopIdParam ? parseInt(shopIdParam, 10) : null);
93	
94	  const fetchApplication = useCallback(async () => {
95	    if (!shopId || !applicationId) return;
96	    setLoading(true);
97	    try {
98	      const response = await fetch(`/api/v1/shops/${shopId}/applications/${applicationId}`, {
99	        headers: { "Authorization": `Bearer ${localStorage.getItem("access_token")}` },
100	      });
101	      if (response.ok) {
102	        const data = await response.json();
103	        setApplication(data);
104	        setFormData({
105	          status: data.status,
106	          assigned_staff_id: data.assigned_staff_id || "",
107	          application_data: data.application_data || {},
108	          notes: data.notes || "",
109	        });
110	      } else if (response.status === 401) {
111	        router.push("/login");
112	      } else {
113	        throw new Error("Failed to fetch application");
114	      }
115	    } catch (err) {
116	      setError(err instanceof Error ? err.message : "An error occurred");
117	    } finally {
118	      setLoading(false);
119	    }
120	  }, [shopId, applicationId, router]);
121	
122	  const fetchStaff = useCallback(async () => {
123	    if (!shopId) return;
124	    try {
125	      const response = await fetch(`/api/v1/shops/${shopId}/staff?page_size=100`, {
126	        headers: { "Authorization": `Bearer ${localStorage.getItem("access_token")}` },
127	      });
128	      if (response.ok) {
129	        const data = await response.json();
130	        setStaff(data.items || data);
131	      }
132	    } catch (err) {
133	      console.error("Failed to fetch staff:", err);
134	    }
135	  }, [shopId]);
136	
137	  useEffect(() => {
138	    if (shopId) {
139	      fetchApplication();
140	      fetchStaff();
141	    }
142	  }, [shopId, fetchApplication, fetchStaff]);
143	
144	  const getStatusBadge = (status: ApplicationStatus) => {
145	    const statusConfigs: Record<ApplicationStatus, { variant: "default" | "secondary" | "destructive" | "outline" | "success" | "warning" | "info"; label: string }> = {
146	      enquiry: { variant: "secondary", label: "Enquiry" },
147	      applied: { variant: "default", label: "Applied" },
148	      documents_pending: { variant: "warning", label: "Documents Pending" },
149	      under_processing: { variant: "info", label: "Under Processing" },
150	      completed: { variant: "success", label: "Completed" },
151	      rejected: { variant: "destructive", label: "Rejected" },
152	      cancelled: { variant: "destructive", label: "Cancelled" },
153	    };
154	    const config = statusConfigs[status] || { variant: "secondary", label: status };
155	    return <Badge variant={config.variant}>{config.label}</Badge>;
156	  };
157	
158	  const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement | HTMLSelectElement>) => {
159	    const { name, value, type } = e.target;
160	    const newValue = type === "checkbox" ? (e.target as HTMLInputElement).checked : value;
161	
162	    if (name === "assigned_staff_id") {
163	      const stringVal = value as string;
164	      setFormData(prev => ({ ...prev, [name]: stringVal === "" ? "" : parseInt(stringVal, 10) }));
165	    } else {
166	      setFormData(prev => ({ ...prev, [name]: newValue }));
167	    }
168	  };
169	
170	  const handleDynamicFieldChange = (fieldName: string, value: any) => {
171	    setFormData(prev => ({
172	      ...prev,
173	      application_data: { ...prev.application_data, [fieldName]: value },
174	    }));
175	  };
176	
177	  const handleSave = async () => {
178	    if (!shopId || !applicationId) return;
179	    setSaving(true);
180	    setError(null);
181	    try {
182	      const payload = {
183	        status: formData.status,
184	        assigned_staff_id: formData.assigned_staff_id || null,
185	        application_data: formData.application_data,
186	        notes: formData.notes || null,
187	      };
188	      const resp = await fetch(`/api/v1/shops/${shopId}/applications/${applicationId}`, {
189	        method: "PATCH",
190	        headers: {
191	          "Content-Type": "application/json",
192	          "Authorization": `Bearer ${localStorage.getItem("access_token")}`,
193	        },
194	        body: JSON.stringify(payload),
195	      });
196	      if (!resp.ok) {
197	        const data = await resp.json();
198	        throw new Error(data.detail || "Failed to update application");
199	      }
200	      const updated = await resp.json();
201	      setApplication(updated);
202	      setEditMode(false);
203	    } catch (err) {
204	      setError(err instanceof Error ? err.message : "An error occurred");
205	    } finally {
206	      setSaving(false);
207	    }
208	  };
209	
210	  if (authLoading) {
211	    return (
212	      <div className="flex min-h-screen items-center justify-center">
213	        <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-primary" />
214	      </div>
215	    );
216	  }
217	
218	  if (loading) {
219	    return (
220	      <ProtectedRoute>
221	        <div className="container mx-auto py-8">
222	          <div className="flex items-center justify-center h-64">
223	            <Loader2 className="h-8 w-8 animate-spin text-primary" />
224	          </div>
225	        </div>
226	      </ProtectedRoute>
227	    );
228	  }
229	
230	  if (error) {
231	    return (
232	      <ProtectedRoute>
233	        <div className="container mx-auto py-8">
234	          <div className="text-center">
235	            <AlertCircle className="h-12 w-12 text-destructive mx-auto mb-4" />
236	            <h2 className="text-xl font-semibold mb-2">Failed to load application</h2>
237	            <p className="text-muted-foreground mb-4">{error}</p>
238	            <Button variant="outline" asChild>
239	              <Link href="/dashboard/applications">
240	                <ArrowLeft className="mr-2 h-4 w-4" />
241	                Back to Applications
242	              </Link>
243	            </Button>
244	          </div>
245	        </div>
246	      </ProtectedRoute>
247	    );
248	  }
249	
250	  if (!application) {
251	    return (
252	      <ProtectedRoute>
253	        <div className="container mx-auto py-8">
254	          <div className="text-center">
255	            <X className="h-12 w-12 text-destructive mx-auto mb-4" />
256	            <h2 className="text-xl font-semibold mb-2">Application not found</h2>
257	            <Button variant="outline" asChild>
258	              <Link href="/dashboard/applications">
259	                <ArrowLeft className="mr-2 h-4 w-4" />
260	                Back to Applications
261	              </Link>
262	            </Button>
263	          </div>
264	        </div>
265	      </ProtectedRoute>
266	    );
267	  }
268	
269	  const statusOrder: ApplicationStatus[] = ["enquiry", "applied", "documents_pending", "under_processing", "completed", "rejected", "cancelled"];
270	  const currentStatusIndex = statusOrder.indexOf(application.status);
271	
272	  return (
273	    <ProtectedRoute>
274	      <div className="container mx-auto py-8">
275	        <div className="flex items-center gap-4 mb-6">
276	          <Button variant="outline" size="icon" asChild>
277	            <Link href={`/dashboard/applications?shop_id=${shopId}`}>
278	              <ArrowLeft className="h-4 w-4" />
279	            </Link>
280	          </Button>
281	          <div className="flex-1">
282	            <h1 className="text-3xl font-bold tracking-tight">{application.application_number}</h1>
283	            <p className="text-muted-foreground mt-1">{application.service.name}</p>
284	          </div>
285	          <div className="flex items-center gap-2">
286	            {getStatusBadge(application.status)}
287	            <Button variant="outline" onClick={() => setEditMode(!editMode)}>
288	              {editMode ? <X className="h-4 w-4" /> : <Edit className="h-4 w-4" />}
289	              {editMode ? "Cancel" : "Edit"}
290	            </Button>
291	          </div>
292	        </div>
293	
294	        {error && (
295	          <div className="mb-6 p-4 rounded-lg bg-destructive/10 text-destructive">
296	            {error}
297	          </div>
298	        )}
299	
300	        {/* Status Timeline */}
301	        <Card className="mb-6">
302	          <CardHeader>
303	            <CardTitle>Status Timeline</CardTitle>
304	            <CardDescription>Track the progress of this application</CardDescription>
305	          </CardHeader>
306	          <CardContent>
307	            <div className="relative pl-4">
308	              <div className="absolute left-2 top-0 bottom-0 w-0.5 bg-muted" />
309	              {statusOrder.map((status, index) => {
310	                const isCompleted = index < currentStatusIndex;
311	                const isCurrent = index === currentStatusIndex;
312	                const isFuture = index > currentStatusIndex;
313	
314	                const statusConfigs: Record<ApplicationStatus, { label: string; icon: React.ReactNode }> = {
315	                  enquiry: { label: "Enquiry", icon: <span className="text-xs">1</span> },
316	                  applied: { label: "Applied", icon: <CheckCircle className="h-4 w-4" /> },
317	                  documents_pending: { label: "Documents Pending", icon: <AlertCircle className="h-4 w-4" /> },
318	                  under_processing: { label: "Under Processing", icon: <Loader2 className="h-4 w-4 animate-spin" /> },
319	                  completed: { label: "Completed", icon: <CheckCircle className="h-4 w-4 text-green-500" /> },
320	                  rejected: { label: "Rejected", icon: <X className="h-4 w-4 text-red-500" /> },
321	                  cancelled: { label: "Cancelled", icon: <X className="h-4 w-4 text-gray-500" /> },
322	                };
323	                const config = statusConfigs[status];
324	
325	                return (
326	                  <div key={status} className="relative flex items-start gap-4 pb-6 last:pb-0">
327	                    <div className={`flex h-8 w-8 items-center justify-center rounded-full border-2 shrink-0 relative z-10 ${
328	                      isCompleted ? "bg-primary border-primary text-primary-foreground" :
329	                      isCurrent ? "bg-primary border-primary text-primary-foreground" :
330	                      "bg-background border-muted text-muted-foreground"
331	                    }`}>
332	                      {isCompleted ? <CheckCircle className="h-4 w-4" /> : config.icon}
333	                    </div>
334	                    <div className="flex-1 pt-1">
335	                      <p className={`font-medium ${isCurrent ? "text-foreground" : isCompleted ? "text-foreground" : "text-muted-foreground"}`}>
336	                        {config.label}
337	                      </p>
338	                      <p className="text-sm text-muted-foreground">
339	                        {isCompleted && application.updated_at && `Updated ${new Date(application.updated_at).toLocaleDateString()}`}
340	                      </p>
341	                    </div>
342	                  </div>
343	                );
344	              })}
345	            </div>
346	          </CardContent>
347	        </Card>
348	
349	        <div className="grid gap-6 md:grid-cols-2 lg:grid-cols-3">
350	          {/* Customer Info */}
351	          <Card>
352	            <CardHeader>
353	              <CardTitle className="flex items-center gap-2">
354	                <Users className="h-5 w-5" />
355	                Customer
356	              </CardTitle>
357	            </CardHeader>
358	            <CardContent className="space-y-3">
359	              <div>
360	                <Label className="text-xs text-muted-foreground">Name</Label>
361	                <p className="font-medium">{application.customer.name}</p>
362	              </div>
363	              <div>
364	                <Label className="text-xs text-muted-foreground">Mobile</Label>
365	                <p className="font-mono">{application.customer.mobile}</p>
366	              </div>
367	              {application.customer.email && (
368	                <div>
369	                  <Label className="text-xs text-muted-foreground">Email</Label>
370	                  <p>{application.customer.email}</p>
371	                </div>
372	              )}
373	              {application.customer.address && (
374	                <div>
375	                  <Label className="text-xs text-muted-foreground">Address</Label>
376	                  <p className="text-sm">{application.customer.address}</p>
377	                </div>
378	              )}
379	              <div className="pt-2 border-t">
380	                <Button variant="outline" size="sm" asChild>
381	                  <Link href={`/dashboard/customers/${application.customer.id}?shop_id=${shopId}`}>
382	                    View Customer Profile
383	                  </Link>
384	                </Button>
385	              </div>
386	            </CardContent>
387	          </Card>
388	
389	          {/* Service Info */}
390	          <Card>
391	            <CardHeader>
392	              <CardTitle className="flex items-center gap-2">
393	                <Banknote className="h-5 w-5" />
394	                Service
395	              </CardTitle>
396	            </CardHeader>
397	            <CardContent className="space-y-3">
398	              <div>
399	                <Label className="text-xs text-muted-foreground">Name</Label>
400	                <p className="font-medium">{application.service.name}</p>
401	              </div>
402	              {application.service.description && (
403	                <div>
404	                  <Label className="text-xs text-muted-foreground">Description</Label>
405	                  <p className="text-sm">{application.service.description}</p>
406	                </div>
407	              )}
408	              <div>
409	                <Label className="text-xs text-muted-foreground">Base Price</Label>
410	                <p className="font-mono">{new Intl.NumberFormat("en-US", { style: "currency", currency: "USD" }).format(application.service.base_price)}</p>
411	              </div>
412	              <div className="pt-2 border-t">
413	                <Button variant="outline" size="sm" asChild>
414	                  <Link href={`/dashboard/services/${application.service.id}?shop_id=${shopId}`}>
415	                    View Service Details
416	                  </Link>
417	                </Button>
418	              </div>
419	            </CardContent>
420	          </Card>
421	
422	          {/* Assigned Staff */}
423	          <Card>
424	            <CardHeader>
425	              <CardTitle className="flex items-center gap-2">
426	                <Users className="h-5 w-5" />
427	                Assigned Staff
428	              </CardTitle>
429	            </CardHeader>
430	            <CardContent>
431	              {application.assigned_staff ? (
432	                <div className="space-y-3">
433	                  <div className="flex items-center gap-3">
434	                    <div className="flex-shrink-0 h-10 w-10 rounded bg-muted/50 flex items-center justify-center">
435	                      <Users className="h-5 w-5 text-muted-foreground" />
436	                    </div>
437	                    <div>
438	                      <p className="font-medium">{application.assigned_staff.full_name}</p>
439	                      <p className="text-sm text-muted-foreground">{application.assigned_staff.email}</p>
440	                    </div>
441	                  </div>
442	                  {editMode && (
443	                    <div className="space-y-2">
444	                      <Label htmlFor="assigned_staff_id">Reassign Staff</Label>
445	                      <Select
446	                        value={formData.assigned_staff_id === "" ? "" : String(formData.assigned_staff_id)}
447	                        onValueChange={(v) => handleChange({ target: { name: "assigned_staff_id", value: v } } as any)}
448	                      >
449	                        <SelectTrigger>
450	                          <SelectValue placeholder="Select staff member" />
451	                        </SelectTrigger>
452	                        <SelectContent>
453	                          <SelectItem value="">Unassign</SelectItem>
454	                          {staff.map((s) => (
455	                            <SelectItem key={s.id} value={String(s.id)}>
456	                              {s.full_name} ({s.email})
457	                            </SelectItem>
458	                          ))}
459	                        </SelectContent>
460	                      </Select>
461	                    </div>
462	                  )}
463	                </div>
464	              ) : (
465	                <div className="space-y-3">
466	                  <p className="text-muted-foreground italic">No staff assigned</p>
467	                  {editMode && (
468	                    <div className="space-y-2">
469	                      <Label htmlFor="assigned_staff_id">Assign Staff</Label>
470	                      <Select
471	                        value={formData.assigned_staff_id === "" ? "" : String(formData.assigned_staff_id)}
472	                        onValueChange={(v) => handleChange({ target: { name: "assigned_staff_id", value: v } } as any)}
473	                      >
474	                        <SelectTrigger>
475	                          <SelectValue placeholder="Select staff member" />
476	                        </SelectTrigger>
477	                        <SelectContent>
478	                          {staff.map((s) => (
479	                            <SelectItem key={s.id} value={String(s.id)}>
480	                              {s.full_name} ({s.email})
481	                            </SelectItem>
482	                          ))}
483	                        </SelectContent>
484	                      </Select>
485	                    </div>
486	                  )}
487	                </div>
488	              )}
489	            </CardContent>
490	          </Card>
491	
492	          {/* Application Data */}
493	          {application.service.fields && application.service.fields.length > 0 && (
494	            <Card className="md:col-span-2 lg:col-span-3">
495	              <CardHeader>
496	                <CardTitle>Service Information</CardTitle>
497	              </CardHeader>
498	              <CardContent className="space-y-4">
499	                {application.service.fields.map((field) => {
500	                  const value = application.application_data?.[field.name];
501	                  const displayValue = value === undefined || value === null || value === ""
502	                    ? <span className="text-muted-foreground italic">Not provided</span>
503	                    : field.field_type === "boolean"
504	                      ? (value ? "Yes" : "No")
505	                      : field.field_type === "date"
506	                        ? new Date(value).toLocaleDateString()
507	                        : String(value);
508	
509	                  return (
510	                    <div key={field.id} className="space-y-1">
511	                      <Label className="text-xs text-muted-foreground">{field.label}</Label>
512	                      {editMode ? (
513	                        <div>
514	                          {field.field_type === "select" && field.options && field.options.length > 0 ? (
515	                            <Select
516	                              value={formData.application_data[field.name] === undefined ? "" : String(formData.application_data[field.name])}
517	                              onValueChange={(v) => handleDynamicFieldChange(field.name, v === "" ? undefined : v)}
518	                            >
519	                              <SelectTrigger>
520	                                <SelectValue placeholder={`Select ${field.label}`} />
521	                              </SelectTrigger>
522	                              <SelectContent>
523	                                <SelectItem value="">Select...</SelectItem>
524	                                {field.options.map((opt) => (
525	                                  <SelectItem key={opt} value={opt}>{opt}</SelectItem>
526	                                ))}
527	                              </SelectContent>
528	                            </Select>
529	                          ) : field.field_type === "boolean" ? (
530	                            <div className="flex items-center gap-2">
531	                              <input
532	                                type="checkbox"
533	                                id={`edit-${field.name}`}
534	                                checked={formData.application_data[field.name] === true}
535	                                onChange={(e) => handleDynamicFieldChange(field.name, e.target.checked)}
536	                                className="h-4 w-4 rounded border-gray-300 text-primary focus:ring-primary"
537	                              />
538	                              <Label htmlFor={`edit-${field.name}`} className="cursor-pointer mb-0">
539	                                {field.label === "Yes" ? "Yes" : "Enabled"}
540	                              </Label>
541	                            </div>
542	                          ) : field.field_type === "textarea" ? (
543	                            <Textarea
544	                              id={`edit-${field.name}`}
545	                              value={formData.application_data[field.name] || ""}
546	                              onChange={(e) => handleDynamicFieldChange(field.name, e.target.value)}
547	                              rows={3}
548	                            />
549	                          ) : field.field_type === "number" ? (
550	                            <Input
551	                              id={`edit-${field.name}`}
552	                              type="number"
553	                              value={formData.application_data[field.name] === undefined ? "" : String(formData.application_data[field.name])}
554	                              onChange={(e) => handleDynamicFieldChange(field.name, e.target.value === "" ? undefined : parseFloat(e.target.value))}
555	                            />
556	                          ) : field.field_type === "date" ? (
557	                            <Input
558	                              id={`edit-${field.name}`}
559	                              type="date"
560	                              value={formData.application_data[field.name] || ""}
561	                              onChange={(e) => handleDynamicFieldChange(field.name, e.target.value || undefined)}
562	                            />
563	                          ) : (
564	                            <Input
565	                              id={`edit-${field.name}`}
566	                              value={formData.application_data[field.name] || ""}
567	                              onChange={(e) => handleDynamicFieldChange(field.name, e.target.value || undefined)}
568	                            />
569	                          )}
570	                        </div>
571	                      ) : (
572	                        <p>{displayValue}</p>
573	                      )}
574	                    </div>
575	                  );
576	                })}
577	              </CardContent>
578	            </Card>
579	          )}
580	
581	          {/* Notes */}
582	          <Card className="md:col-span-2 lg:col-span-3">
583	            <CardHeader>
584	              <CardTitle>Internal Notes</CardTitle>
585	            </CardHeader>
586	            <CardContent>
587	              {editMode ? (
588	                <div className="space-y-2">
589	                  <Label htmlFor="notes">Notes</Label>
590	                  <Textarea
591	                    id="notes"
592	                    value={formData.notes}
593	                    onChange={handleChange}
594	                    rows={4}
595	                    placeholder="Add internal notes..."
596	                  />
597	                </div>
598	              ) : (
599	                <p className={application.notes ? "" : "text-muted-foreground italic"}>
600	                  {application.notes || "No notes added"}
601	                </p>
602	              )}
603	            </CardContent>
604	          </Card>
605	
606	          {/* Metadata */}
607	          <Card className="md:col-span-2 lg:col-span-3">
608	            <CardHeader>
609	              <CardTitle>Application Details</CardTitle>
610	            </CardHeader>
611	            <CardContent className="grid gap-4 sm:grid-cols-2">
612	              <div>
613	                <Label className="text-xs text-muted-foreground">Created</Label>
614	                <p>{new Date(application.created_at).toLocaleString()}</p>
615	              </div>
616	              <div>
617	                <Label className="text-xs text-muted-foreground">Last Updated</Label>
618	                <p>{new Date(application.updated_at).toLocaleString()}</p>
619	              </div>
620	              <div>
621	                <Label className="text-xs text-muted-foreground">Customer ID</Label>
622	                <p className="font-mono">{application.customer_id}</p>
623	              </div>
624	              <div>
625	                <Label className="text-xs text-muted-foreground">Service ID</Label>
626	                <p className="font-mono">{application.service_id}</p>
627	              </div>
628	            </CardContent>
629	          </Card>
630	        </div>
631	
632	        {editMode && (
633	          <div className="mt-6 flex justify-end gap-3">
634	            <Button variant="outline" onClick={() => {
635	              setFormData({
636	                status: application.status,
637	                assigned_staff_id: application.assigned_staff_id || "",
638	                application_data: application.application_data || {},
639	                notes: application.notes || "",
640	              });
641	              setEditMode(false);
642	            }}>
643	              Cancel
644	            </Button>
645	            <Button onClick={handleSave} disabled={saving}>
646	              <Save className="mr-2 h-4 w-4" />
647	              {saving ? "Saving..." : "Save Changes"}
648	            </Button>
649	          </div>
650	        )}
651	      </div>
652	    </ProtectedRoute>
653	  );
654	}
655	
656	export default function ApplicationDetailPage() {
657	  return <ApplicationDetailContent />;
658	}

