71	function ApplicationDetailContent() {
72	  const { user, loading: authLoading } = useAuth();
73	  const router = useRouter();
74	  const params = useParams();
75	  const applicationId = params?.id as string;
76	
77	  const [loading, setLoading] = useState(true);
78	  const [error, setError] = useState<string | null>(null);
79	  const [application, setApplication] = useState<Application | null>(null);
80	  const [staff, setStaff] = useState<Staff[]>([]);
81	  const [saving, setSaving] = useState(false);
82	  const [editMode, setEditMode] = useState(false);
83	
84	  // Form data for editing
85	  const [formData, setFormData] = useState({
86	    status: "" as ApplicationStatus | "",
87	    assigned_staff_id: "" as number | "",
88	    application_data: {} as Record<string, any>,
89	    notes: "",
90	  });
91	
92	  const shopIdParam = new URLSearchParams(window.location.search).get("shop_id");
93	  const [shopId, setShopId] = useState<number | null>(shopIdParam ? parseInt(shopIdParam, 10) : null);
94	
95	  const fetchApplication = useCallback(async () => {
96	    if (!shopId || !applicationId) return;
97	    setLoading(true);
98	    try {
99	      const response = await fetch(`/api/v1/shops/${shopId}/applications/${applicationId}`, {
100	        headers: { "Authorization": `Bearer ${localStorage.getItem("access_token")}` },
101	      });
102	      if (response.ok) {
103	        const data = await response.json();
104	        setApplication(data);
105	        setFormData({
106	          status: data.status,
107	          assigned_staff_id: data.assigned_staff_id || "",
108	          application_data: data.application_data || {},
109	          notes: data.notes || "",
110	        });
111	      } else if (response.status === 401) {
112	        router.push("/login");
113	      } else {
114	        throw new Error("Failed to fetch application");
115	      }
116	    } catch (err) {
117	      setError(err instanceof Error ? err.message : "An error occurred");
118	    } finally {
119	      setLoading(false);
120	    }
121	  }, [shopId, applicationId, router]);
122	
123	  const fetchStaff = useCallback(async () => {
124	    if (!shopId) return;
125	    try {
126	      const response = await fetch(`/api/v1/shops/${shopId}/staff?page_size=100`, {
127	        headers: { "Authorization": `Bearer ${localStorage.getItem("access_token")}` },
128	      });
129	      if (response.ok) {
130	        const data = await response.json();
131	        setStaff(data.items || data);
132	      }
133	    } catch (err) {
134	      console.error("Failed to fetch staff:", err);
135	    }
136	  }, [shopId]);
137	
138	  useEffect(() => {
139	    if (shopId) {
140	      fetchApplication();
141	      fetchStaff();
142	    }
143	  }, [shopId, fetchApplication, fetchStaff]);
144	
145	  const getStatusBadge = (status: ApplicationStatus) => {
146	    const statusConfigs: Record<ApplicationStatus, { variant: "default" | "secondary" | "destructive" | "outline" | "success" | "warning" | "info"; label: string }> = {
147	      enquiry: { variant: "secondary", label: "Enquiry" },
148	      applied: { variant: "default", label: "Applied" },
149	      documents_pending: { variant: "warning", label: "Documents Pending" },
150	      under_processing: { variant: "info", label: "Under Processing" },
151	      completed: { variant: "success", label: "Completed" },
152	      rejected: { variant: "destructive", label: "Rejected" },
153	      cancelled: { variant: "destructive", label: "Cancelled" },
154	    };
155	    const config = statusConfigs[status] || { variant: "secondary", label: status };
156	    return <Badge variant={config.variant}>{config.label}</Badge>;
157	  };
158	
159	  const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement | HTMLSelectElement>) => {
160	    const { name, value, type } = e.target;
161	    const newValue = type === "checkbox" ? (e.target as HTMLInputElement).checked : value;
162	
163	    if (name === "assigned_staff_id") {
164	      const stringVal = value as string;
165	      setFormData(prev => ({ ...prev, [name]: stringVal === "" ? "" : parseInt(stringVal, 10) }));
166	    } else {
167	      setFormData(prev => ({ ...prev, [name]: newValue }));
168	    }
169	  };
170	
171	  const handleDynamicFieldChange = (fieldName: string, value: any) => {
172	    setFormData(prev => ({
173	      ...prev,
174	      application_data: { ...prev.application_data, [fieldName]: value },
175	    }));
176	  };
177	
178	  const handleSave = async () => {
179	    if (!shopId || !applicationId) return;
180	    setSaving(true);
181	    setError(null);
182	    try {
183	      const payload = {
184	        status: formData.status,
185	        assigned_staff_id: formData.assigned_staff_id || null,
186	        application_data: formData.application_data,
187	        notes: formData.notes || null,
188	      };
189	      const resp = await fetch(`/api/v1/shops/${shopId}/applications/${applicationId}`, {
190	        method: "PATCH",
191	        headers: {
192	          "Content-Type": "application/json",
193	          "Authorization": `Bearer ${localStorage.getItem("access_token")}`,
194	        },
195	        body: JSON.stringify(payload),
196	      });
197	      if (!resp.ok) {
198	        const data = await resp.json();
199	        throw new Error(data.detail || "Failed to update application");
200	      }
201	      const updated = await resp.json();
202	      setApplication(updated);
203	      setEditMode(false);
204	    } catch (err) {
205	      setError(err instanceof Error ? err.message : "An error occurred");
206	    } finally {
207	      setSaving(false);
208	    }
209	  };
210	
211	  if (authLoading) {
212	    return (
213	      <div className="flex min-h-screen items-center justify-center">
214	        <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-primary" />
215	      </div>
216	    );
217	  }
218	
219	  if (loading) {
220	    return (
221	      <ProtectedRoute>
222	        <div className="container mx-auto py-8">
223	          <div className="flex items-center justify-center h-64">
224	            <Loader2 className="h-8 w-8 animate-spin text-primary" />
225	          </div>
226	        </div>
227	      </ProtectedRoute>
228	    );
229	  }
230	
231	  if (error) {
232	    return (
233	      <ProtectedRoute>
234	        <div className="container mx-auto py-8">
235	          <div className="text-center">
236	            <AlertCircle className="h-12 w-12 text-destructive mx-auto mb-4" />
237	            <h2 className="text-xl font-semibold mb-2">Failed to load application</h2>
238	            <p className="text-muted-foreground mb-4">{error}</p>
239	            <Button variant="outline" asChild>
240	              <Link href="/dashboard/applications">
241	                <ArrowLeft className="mr-2 h-4 w-4" />
242	                Back to Applications
243	              </Link>
244	            </Button>
245	          </div>
246	        </div>
247	      </ProtectedRoute>
248	    );
249	  }
250	
251	  if (!application) {
252	    return (
253	      <ProtectedRoute>
254	        <div className="container mx-auto py-8">
255	          <div className="text-center">
256	            <X className="h-12 w-12 text-destructive mx-auto mb-4" />
257	            <h2 className="text-xl font-semibold mb-2">Application not found</h2>
258	            <Button variant="outline" asChild>
259	              <Link href="/dashboard/applications">
260	                <ArrowLeft className="mr-2 h-4 w-4" />
261	                Back to Applications
262	              </Link>
263	            </Button>
264	          </div>
265	        </div>
266	      </ProtectedRoute>
267	    );
268	  }
269	
270	  const statusOrder: ApplicationStatus[] = ["enquiry", "applied", "documents_pending", "under_processing", "completed", "rejected", "cancelled"];
271	  const currentStatusIndex = statusOrder.indexOf(application.status);
272	
273	  return (
274	    <ProtectedRoute>
275	      <div className="container mx-auto py-8">
276	        <div className="flex items-center gap-4 mb-6">
277	          <Button variant="outline" size="icon" asChild>
278	            <Link href={`/dashboard/applications?shop_id=${shopId}`}>
279	              <ArrowLeft className="h-4 w-4" />
280	            </Link>
281	          </Button>
282	          <div className="flex-1">
283	            <h1 className="text-3xl font-bold tracking-tight">{application.application_number}</h1>
284	            <p className="text-muted-foreground mt-1">{application.service.name}</p>
285	          </div>
286	          <div className="flex items-center gap-2">
287	            {getStatusBadge(application.status)}
288	            <Button variant="outline" onClick={() => setEditMode(!editMode)}>
289	              {editMode ? <X className="h-4 w-4" /> : <Edit className="h-4 w-4" />}
290	              {editMode ? "Cancel" : "Edit"}
291	            </Button>
292	          </div>
293	        </div>
294	
295	        {error && (
296	          <div className="mb-6 p-4 rounded-lg bg-destructive/10 text-destructive">
297	            {error}
298	          </div>
299	        )}
300	
301	        {/* Status Timeline */}
302	        <Card className="mb-6">
303	          <CardHeader>
304	            <CardTitle>Status Timeline</CardTitle>
305	            <CardDescription>Track the progress of this application</CardDescription>
306	          </CardHeader>
307	          <CardContent>
308	            <div className="relative pl-4">
309	              <div className="absolute left-2 top-0 bottom-0 w-0.5 bg-muted" />
310	              {statusOrder.map((status, index) => {
311	                const isCompleted = index < currentStatusIndex;
312	                const isCurrent = index === currentStatusIndex;
313	                const isFuture = index > currentStatusIndex;
314	
315	                const statusConfigs: Record<ApplicationStatus, { label: string; icon: React.ReactNode }> = {
316	                  enquiry: { label: "Enquiry", icon: <span className="text-xs">1</span> },
317	                  applied: { label: "Applied", icon: <CheckCircle className="h-4 w-4" /> },
318	                  documents_pending: { label: "Documents Pending", icon: <AlertCircle className="h-4 w-4" /> },
319	                  under_processing: { label: "Under Processing", icon: <Loader2 className="h-4 w-4 animate-spin" /> },
320	                  completed: { label: "Completed", icon: <CheckCircle className="h-4 w-4 text-green-500" /> },
321	                  rejected: { label: "Rejected", icon: <X className="h-4 w-4 text-red-500" /> },
322	                  cancelled: { label: "Cancelled", icon: <X className="h-4 w-4 text-gray-500" /> },
323	                };
324	                const config = statusConfigs[status];
325	
326	                return (
327	                  <div key={status} className="relative flex items-start gap-4 pb-6 last:pb-0">
328	                    <div className={`flex h-8 w-8 items-center justify-center rounded-full border-2 shrink-0 relative z-10 ${
329	                      isCompleted ? "bg-primary border-primary text-primary-foreground" :
330	                      isCurrent ? "bg-primary border-primary text-primary-foreground" :
331	                      "bg-background border-muted text-muted-foreground"
332	                    }`}>
333	                      {isCompleted ? <CheckCircle className="h-4 w-4" /> : config.icon}
334	                    </div>
335	                    <div className="flex-1 pt-1">
336	                      <p className={`font-medium ${isCurrent ? "text-foreground" : isCompleted ? "text-foreground" : "text-muted-foreground"}`}>
337	                        {config.label}
338	                      </p>
339	                      <p className="text-sm text-muted-foreground">
340	                        {isCompleted && application.updated_at && `Updated ${new Date(application.updated_at).toLocaleDateString()}`}
341	                      </p>
342	                    </div>
343	                  </div>
344	                );
345	              })}
346	            </div>
347	          </CardContent>
348	        </Card>
349	
350	        <div className="grid gap-6 md:grid-cols-2 lg:grid-cols-3">
351	          {/* Customer Info */}
352	          <Card>
353	            <CardHeader>
354	              <CardTitle className="flex items-center gap-2">
355	                <Users className="h-5 w-5" />
356	                Customer
357	              </CardTitle>
358	            </CardHeader>
359	            <CardContent className="space-y-3">
360	              <div>
361	                <Label className="text-xs text-muted-foreground">Name</Label>
362	                <p className="font-medium">{application.customer.name}</p>
363	              </div>
364	              <div>
365	                <Label className="text-xs text-muted-foreground">Mobile</Label>
366	                <p className="font-mono">{application.customer.mobile}</p>
367	              </div>
368	              {application.customer.email && (
369	                <div>
370	                  <Label className="text-xs text-muted-foreground">Email</Label>
371	                  <p>{application.customer.email}</p>
372	                </div>
373	              )}
374	              {application.customer.address && (
375	                <div>
376	                  <Label className="text-xs text-muted-foreground">Address</Label>
377	                  <p className="text-sm">{application.customer.address}</p>
378	                </div>
379	              )}
380	              <div className="pt-2 border-t">
381	                <Button variant="outline" size="sm" asChild>
382	                  <Link href={`/dashboard/customers/${application.customer.id}?shop_id=${shopId}`}>
383	                    View Customer Profile
384	                  </Link>
385	                </Button>
386	              </div>
387	            </CardContent>
388	          </Card>
389	
390	          {/* Service Info */}
391	          <Card>
392	            <CardHeader>
393	              <CardTitle className="flex items-center gap-2">
394	                <Banknote className="h-5 w-5" />
395	                Service
396	              </CardTitle>
397	            </CardHeader>
398	            <CardContent className="space-y-3">
399	              <div>
400	                <Label className="text-xs text-muted-foreground">Name</Label>
401	                <p className="font-medium">{application.service.name}</p>
402	              </div>
403	              {application.service.description && (
404	                <div>
405	                  <Label className="text-xs text-muted-foreground">Description</Label>
406	                  <p className="text-sm">{application.service.description}</p>
407	                </div>
408	              )}
409	              <div>
410	                <Label className="text-xs text-muted-foreground">Base Price</Label>
411	                <p className="font-mono">{new Intl.NumberFormat("en-US", { style: "currency", currency: "USD" }).format(application.service.base_price)}</p>
412	              </div>
413	              <div className="pt-2 border-t">
414	                <Button variant="outline" size="sm" asChild>
415	                  <Link href={`/dashboard/services/${application.service.id}?shop_id=${shopId}`}>
416	                    View Service Details
417	                  </Link>
418	                </Button>
419	              </div>
420	            </CardContent>
421	          </Card>
422	
423	          {/* Assigned Staff */}
424	          <Card>
425	            <CardHeader>
426	              <CardTitle className="flex items-center gap-2">
427	                <Users className="h-5 w-5" />
428	                Assigned Staff
429	              </CardTitle>
430	            </CardHeader>
431	            <CardContent>
432	              {application.assigned_staff ? (
433	                <div className="space-y-3">
434	                  <div className="flex items-center gap-3">
435	                    <div className="flex-shrink-0 h-10 w-10 rounded bg-muted/50 flex items-center justify-center">
436	                      <Users className="h-5 w-5 text-muted-foreground" />
437	                    </div>
438	                    <div>
439	                      <p className="font-medium">{application.assigned_staff.full_name}</p>
440	                      <p className="text-sm text-muted-foreground">{application.assigned_staff.email}</p>
441	                    </div>
442	                  </div>
443	                  {editMode && (
444	                    <div className="space-y-2">
445	                      <Label htmlFor="assigned_staff_id">Reassign Staff</Label>
446	                      <Select
447	                        value={formData.assigned_staff_id === "" ? "" : String(formData.assigned_staff_id)}
448	                        onValueChange={(v) => handleChange({ target: { name: "assigned_staff_id", value: v } } as any)}
449	                      >
450	                        <SelectTrigger>
451	                          <SelectValue placeholder="Select staff member" />
452	                        </SelectTrigger>
453	                        <SelectContent>
454	                          <SelectItem value="">Unassign</SelectItem>
455	                          {staff.map((s) => (
456	                            <SelectItem key={s.id} value={String(s.id)}>
457	                              {s.full_name} ({s.email})
458	                            </SelectItem>
459	                          ))}
460	                        </SelectContent>
461	                      </Select>
462	                    </div>
463	                  )}
464	                </div>
465	              ) : (
466	                <div className="space-y-3">
467	                  <p className="text-muted-foreground italic">No staff assigned</p>
468	                  {editMode && (
469	                    <div className="space-y-2">
470	                      <Label htmlFor="assigned_staff_id">Assign Staff</Label>
471	                      <Select
472	                        value={formData.assigned_staff_id === "" ? "" : String(formData.assigned_staff_id)}
473	                        onValueChange={(v) => handleChange({ target: { name: "assigned_staff_id", value: v } } as any)}
474	                      >
475	                        <SelectTrigger>
476	                          <SelectValue placeholder="Select staff member" />
477	                        </SelectTrigger>
478	                        <SelectContent>
479	                          {staff.map((s) => (
480	                            <SelectItem key={s.id} value={String(s.id)}>
481	                              {s.full_name} ({s.email})
482	                            </SelectItem>
483	                          ))}
484	                        </SelectContent>
485	                      </Select>
486	                    </div>
487	                  )}
488	                </div>
489	              )}
490	            </CardContent>
491	          </Card>
492	
493	          {/* Application Data */}
494	          {application.service.fields && application.service.fields.length > 0 && (
495	            <Card className="md:col-span-2 lg:col-span-3">
496	              <CardHeader>
497	                <CardTitle>Service Information</CardTitle>
498	              </CardHeader>
499	              <CardContent className="space-y-4">
500	                {application.service.fields.map((field) => {
501	                  const value = application.application_data?.[field.name];
502	                  const displayValue = value === undefined || value === null || value === ""
503	                    ? <span className="text-muted-foreground italic">Not provided</span>
504	                    : field.field_type === "boolean"
505	                      ? (value ? "Yes" : "No")
506	                      : field.field_type === "date"
507	                        ? new Date(value).toLocaleDateString()
508	                        : String(value);
509	
510	                  return (
511	                    <div key={field.id} className="space-y-1">
512	                      <Label className="text-xs text-muted-foreground">{field.label}</Label>
513	                      {editMode ? (
514	                        <div>
515	                          {field.field_type === "select" && field.options && field.options.length > 0 ? (
516	                            <Select
517	                              value={formData.application_data[field.name] === undefined ? "" : String(formData.application_data[field.name])}
518	                              onValueChange={(v) => handleDynamicFieldChange(field.name, v === "" ? undefined : v)}
519	                            >
520	                              <SelectTrigger>
521	                                <SelectValue placeholder={`Select ${field.label}`} />
522	                              </SelectTrigger>
523	                              <SelectContent>
524	                                <SelectItem value="">Select...</SelectItem>
525	                                {field.options.map((opt) => (
526	                                  <SelectItem key={opt} value={opt}>{opt}</SelectItem>
527	                                ))}
528	                              </SelectContent>
529	                            </Select>
530	                          ) : field.field_type === "boolean" ? (
531	                            <div className="flex items-center gap-2">
532	                              <input
533	                                type="checkbox"
534	                                id={`edit-${field.name}`}
535	                                checked={formData.application_data[field.name] === true}
536	                                onChange={(e) => handleDynamicFieldChange(field.name, e.target.checked)}
537	                                className="h-4 w-4 rounded border-gray-300 text-primary focus:ring-primary"
538	                              />
539	                              <Label htmlFor={`edit-${field.name}`} className="cursor-pointer mb-0">
540	                                {field.label === "Yes" ? "Yes" : "Enabled"}
541	                              </Label>
542	                            </div>
543	                          ) : field.field_type === "textarea" ? (
544	                            <Textarea
545	                              id={`edit-${field.name}`}
546	                              value={formData.application_data[field.name] || ""}
547	                              onChange={(e) => handleDynamicFieldChange(field.name, e.target.value)}
548	                              rows={3}
549	                            />
550	                          ) : field.field_type === "number" ? (
551	                            <Input
552	                              id={`edit-${field.name}`}
553	                              type="number"
554	                              value={formData.application_data[field.name] === undefined ? "" : String(formData.application_data[field.name])}
555	                              onChange={(e) => handleDynamicFieldChange(field.name, e.target.value === "" ? undefined : parseFloat(e.target.value))}
556	                            />
557	                          ) : field.field_type === "date" ? (
558	                            <Input
559	                              id={`edit-${field.name}`}
560	                              type="date"
561	                              value={formData.application_data[field.name] || ""}
562	                              onChange={(e) => handleDynamicFieldChange(field.name, e.target.value || undefined)}
563	                            />
564	                          ) : (
565	                            <Input
566	                              id={`edit-${field.name}`}
567	                              value={formData.application_data[field.name] || ""}
568	                              onChange={(e) => handleDynamicFieldChange(field.name, e.target.value || undefined)}
569	                            />
570	                          )}
571	                        </div>
572	                      ) : (
573	                        <p>{displayValue}</p>
574	                      )}
575	                    </div>
576	                  );
577	                })}
578	              </CardContent>
579	            </Card>
580	          )}
581	
582	          {/* Notes */}
583	          <Card className="md:col-span-2 lg:col-span-3">
584	            <CardHeader>
585	              <CardTitle>Internal Notes</CardTitle>
586	            </CardHeader>
587	            <CardContent>
588	              {editMode ? (
589	                <div className="space-y-2">
590	                  <Label htmlFor="notes">Notes</Label>
591	                  <Textarea
592	                    id="notes"
593	                    value={formData.notes}
594	                    onChange={handleChange}
595	                    rows={4}
596	                    placeholder="Add internal notes..."
597	                  />
598	                </div>
599	              ) : (
600	                <p className={application.notes ? "" : "text-muted-foreground italic"}>
601	                  {application.notes || "No notes added"}
602	                </p>
603	              )}
604	            </CardContent>
605	          </Card>
606	
607	          {/* Metadata */}
608	          <Card className="md:col-span-2 lg:col-span-3">
609	            <CardHeader>
610	              <CardTitle>Application Details</CardTitle>
611	            </CardHeader>
612	            <CardContent className="grid gap-4 sm:grid-cols-2">
613	              <div>
614	                <Label className="text-xs text-muted-foreground">Created</Label>
615	                <p>{new Date(application.created_at).toLocaleString()}</p>
616	              </div>
617	              <div>
618	                <Label className="text-xs text-muted-foreground">Last Updated</Label>
619	                <p>{new Date(application.updated_at).toLocaleString()}</p>
620	              </div>
621	              <div>
622	                <Label className="text-xs text-muted-foreground">Customer ID</Label>
623	                <p className="font-mono">{application.customer_id}</p>
624	              </div>
625	              <div>
626	                <Label className="text-xs text-muted-foreground">Service ID</Label>
627	                <p className="font-mono">{application.service_id}</p>
628	              </div>
629	            </CardContent>
630	          </Card>
631	        </div>
632	
633	        {/* Document Management Section */}
634	        {shopId && application && (
635	          <div className="mt-8">
636	            <DocumentManager
637	              shopId={shopId}
638	              applicationId={application.id}
639	              canUpload={true}
640	              canVerify={true}
641	              canReject={true}
642	              canDelete={true}
643	              onChecklistUpdated={fetchApplication}
644	            />
645	          </div>
646	        )}
647	
648	        {editMode && (
649	          <div className="mt-6 flex justify-end gap-3">
650	            <Button variant="outline" onClick={() => {
651	              setFormData({
652	                status: application.status,
653	                assigned_staff_id: application.assigned_staff_id || "",
654	                application_data: application.application_data || {},
655	                notes: application.notes || "",
656	              });
657	              setEditMode(false);
658	            }}>
659	              Cancel
660	            </Button>
661	            <Button onClick={handleSave} disabled={saving}>
662	              <Save className="mr-2 h-4 w-4" />
663	              {saving ? "Saving..." : "Save Changes"}
664	            </Button>
665	          </div>
666	        )}
667	      </div>
668	    </ProtectedRoute>
669	  );
670	}
671	
672	export default function ApplicationDetailPage() {
673	  return <ApplicationDetailContent />;
674	}

