"use client";

import { useState, useEffect, useCallback } from "react";
import { useRouter, useParams } from "next/navigation";
import { useAuth } from "@/lib/auth-context";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { ProtectedRoute } from "@/components/protected-route";
import Link from "next/link";
import { ArrowLeft, Edit, Users, Banknote, ChevronLeft, ChevronRight, Save, X, CheckCircle, AlertCircle, Loader2 } from "lucide-react";
import { Badge } from "@/components/ui/badge";
import { ApplicationStatus } from "@/src/types/application";
import { DocumentManager } from "@/components/documents/document-manager";

interface Application {
  id: number;
  application_number: string;
  customer_id: number;
  customer: {
    id: number;
    name: string;
    mobile: string;
    email?: string;
    address?: string;
  };
  service_id: number;
  service: {
    id: number;
    name: string;
    description?: string;
    base_price: number;
    fields: ServiceField[];
  };
  status: ApplicationStatus;
  assigned_staff_id?: number | null;
  assigned_staff?: {
    id: number;
    full_name: string;
    email: string;
  } | null;
  application_data: Record<string, any>;
  notes?: string;
  created_at: string;
  updated_at: string;
}

interface ServiceField {
  id: number;
  service_id: number;
  name: string;
  label: string;
  field_type: 'text' | 'number' | 'date' | 'select' | 'textarea' | 'boolean';
  is_required: boolean;
  options?: string[];
  help_text?: string;
  order: number;
}

interface Staff {
  id: number;
  email: string;
  full_name: string;
  is_active: boolean;
  platform_role?: string;
}

function ApplicationDetailContent() {
  const { user, loading: authLoading } = useAuth();
  const router = useRouter();
  const params = useParams();
  const applicationId = params?.id as string;

  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [application, setApplication] = useState<Application | null>(null);
  const [staff, setStaff] = useState<Staff[]>([]);
  const [saving, setSaving] = useState(false);
  const [editMode, setEditMode] = useState(false);

  // Form data for editing
  const [formData, setFormData] = useState({
    status: "" as ApplicationStatus | "",
    assigned_staff_id: "" as number | "",
    application_data: {} as Record<string, any>,
    notes: "",
  });

  const shopIdParam = new URLSearchParams(window.location.search).get("shop_id");
  const [shopId, setShopId] = useState<number | null>(shopIdParam ? parseInt(shopIdParam, 10) : null);

  const fetchApplication = useCallback(async () => {
    if (!shopId || !applicationId) return;
    setLoading(true);
    try {
      const response = await fetch(`/api/v1/shops/${shopId}/applications/${applicationId}`, {
        headers: { "Authorization": `Bearer ${localStorage.getItem("access_token")}` },
      });
      if (response.ok) {
        const data = await response.json();
        setApplication(data);
        setFormData({
          status: data.status,
          assigned_staff_id: data.assigned_staff_id || "",
          application_data: data.application_data || {},
          notes: data.notes || "",
        });
      } else if (response.status === 401) {
        router.push("/login");
      } else {
        throw new Error("Failed to fetch application");
      }
    } catch (err) {
      setError(err instanceof Error ? err.message : "An error occurred");
    } finally {
      setLoading(false);
    }
  }, [shopId, applicationId, router]);

  const fetchStaff = useCallback(async () => {
    if (!shopId) return;
    try {
      const response = await fetch(`/api/v1/shops/${shopId}/staff?page_size=100`, {
        headers: { "Authorization": `Bearer ${localStorage.getItem("access_token")}` },
      });
      if (response.ok) {
        const data = await response.json();
        setStaff(data.items || data);
      }
    } catch (err) {
      console.error("Failed to fetch staff:", err);
    }
  }, [shopId]);

  useEffect(() => {
    if (shopId) {
      fetchApplication();
      fetchStaff();
    }
  }, [shopId, fetchApplication, fetchStaff]);

  const getStatusBadge = (status: ApplicationStatus) => {
    const statusConfigs: Record<ApplicationStatus, { variant: "default" | "secondary" | "destructive" | "outline" | "success" | "warning" | "info"; label: string }> = {
      enquiry: { variant: "secondary", label: "Enquiry" },
      applied: { variant: "default", label: "Applied" },
      documents_pending: { variant: "warning", label: "Documents Pending" },
      under_processing: { variant: "info", label: "Under Processing" },
      completed: { variant: "success", label: "Completed" },
      rejected: { variant: "destructive", label: "Rejected" },
      cancelled: { variant: "destructive", label: "Cancelled" },
    };
    const config = statusConfigs[status] || { variant: "secondary", label: status };
    return <Badge variant={config.variant}>{config.label}</Badge>;
  };

  const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement | HTMLSelectElement>) => {
    const { name, value, type } = e.target;
    const newValue = type === "checkbox" ? (e.target as HTMLInputElement).checked : value;

    if (name === "assigned_staff_id") {
      const stringVal = value as string;
      setFormData(prev => ({ ...prev, [name]: stringVal === "" ? "" : parseInt(stringVal, 10) }));
    } else {
      setFormData(prev => ({ ...prev, [name]: newValue }));
    }
  };

  const handleDynamicFieldChange = (fieldName: string, value: any) => {
    setFormData(prev => ({
      ...prev,
      application_data: { ...prev.application_data, [fieldName]: value },
    }));
  };

  const handleSave = async () => {
    if (!shopId || !applicationId) return;
    setSaving(true);
    setError(null);
    try {
      const payload = {
        status: formData.status,
        assigned_staff_id: formData.assigned_staff_id || null,
        application_data: formData.application_data,
        notes: formData.notes || null,
      };
      const resp = await fetch(`/api/v1/shops/${shopId}/applications/${applicationId}`, {
        method: "PATCH",
        headers: {
          "Content-Type": "application/json",
          "Authorization": `Bearer ${localStorage.getItem("access_token")}`,
        },
        body: JSON.stringify(payload),
      });
      if (!resp.ok) {
        const data = await resp.json();
        throw new Error(data.detail || "Failed to update application");
      }
      const updated = await resp.json();
      setApplication(updated);
      setEditMode(false);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An error occurred");
    } finally {
      setSaving(false);
    }
  };

  if (authLoading) {
    return (
      <div className="flex min-h-screen items-center justify-center">
        <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-primary" />
      </div>
    );
  }

  if (loading) {
    return (
      <ProtectedRoute>
        <div className="container mx-auto py-8">
          <div className="flex items-center justify-center h-64">
            <Loader2 className="h-8 w-8 animate-spin text-primary" />
          </div>
        </div>
      </ProtectedRoute>
    );
  }

  if (error) {
    return (
      <ProtectedRoute>
        <div className="container mx-auto py-8">
          <div className="text-center">
            <AlertCircle className="h-12 w-12 text-destructive mx-auto mb-4" />
            <h2 className="text-xl font-semibold mb-2">Failed to load application</h2>
            <p className="text-muted-foreground mb-4">{error}</p>
            <Button variant="outline" asChild>
              <Link href="/dashboard/applications">
                <ArrowLeft className="mr-2 h-4 w-4" />
                Back to Applications
              </Link>
            </Button>
          </div>
        </div>
      </ProtectedRoute>
    );
  }

  if (!application) {
    return (
      <ProtectedRoute>
        <div className="container mx-auto py-8">
          <div className="text-center">
            <X className="h-12 w-12 text-destructive mx-auto mb-4" />
            <h2 className="text-xl font-semibold mb-2">Application not found</h2>
            <Button variant="outline" asChild>
              <Link href="/dashboard/applications">
                <ArrowLeft className="mr-2 h-4 w-4" />
                Back to Applications
              </Link>
            </Button>
          </div>
        </div>
      </ProtectedRoute>
    );
  }

  const statusOrder: ApplicationStatus[] = ["enquiry", "applied", "documents_pending", "under_processing", "completed", "rejected", "cancelled"];
  const currentStatusIndex = statusOrder.indexOf(application.status);

  return (
    <ProtectedRoute>
      <div className="container mx-auto py-8">
        <div className="flex items-center gap-4 mb-6">
          <Button variant="outline" size="icon" asChild>
            <Link href={`/dashboard/applications?shop_id=${shopId}`}>
              <ArrowLeft className="h-4 w-4" />
            </Link>
          </Button>
          <div className="flex-1">
            <h1 className="text-3xl font-bold tracking-tight">{application.application_number}</h1>
            <p className="text-muted-foreground mt-1">{application.service.name}</p>
          </div>
          <div className="flex items-center gap-2">
            {getStatusBadge(application.status)}
            <Button variant="outline" onClick={() => setEditMode(!editMode)}>
              {editMode ? <X className="h-4 w-4" /> : <Edit className="h-4 w-4" />}
              {editMode ? "Cancel" : "Edit"}
            </Button>
          </div>
        </div>

        {error && (
          <div className="mb-6 p-4 rounded-lg bg-destructive/10 text-destructive">
            {error}
          </div>
        )}

        {/* Status Timeline */}
        <Card className="mb-6">
          <CardHeader>
            <CardTitle>Status Timeline</CardTitle>
            <CardDescription>Track the progress of this application</CardDescription>
          </CardHeader>
          <CardContent>
            <div className="relative pl-4">
              <div className="absolute left-2 top-0 bottom-0 w-0.5 bg-muted" />
              {statusOrder.map((status, index) => {
                const isCompleted = index < currentStatusIndex;
                const isCurrent = index === currentStatusIndex;
                const isFuture = index > currentStatusIndex;

                const statusConfigs: Record<ApplicationStatus, { label: string; icon: React.ReactNode }> = {
                  enquiry: { label: "Enquiry", icon: <span className="text-xs">1</span> },
                  applied: { label: "Applied", icon: <CheckCircle className="h-4 w-4" /> },
                  documents_pending: { label: "Documents Pending", icon: <AlertCircle className="h-4 w-4" /> },
                  under_processing: { label: "Under Processing", icon: <Loader2 className="h-4 w-4 animate-spin" /> },
                  completed: { label: "Completed", icon: <CheckCircle className="h-4 w-4 text-green-500" /> },
                  rejected: { label: "Rejected", icon: <X className="h-4 w-4 text-red-500" /> },
                  cancelled: { label: "Cancelled", icon: <X className="h-4 w-4 text-gray-500" /> },
                };
                const config = statusConfigs[status];

                return (
                  <div key={status} className="relative flex items-start gap-4 pb-6 last:pb-0">
                    <div className={`flex h-8 w-8 items-center justify-center rounded-full border-2 shrink-0 relative z-10 ${
                      isCompleted ? "bg-primary border-primary text-primary-foreground" :
                      isCurrent ? "bg-primary border-primary text-primary-foreground" :
                      "bg-background border-muted text-muted-foreground"
                    }`}>
                      {isCompleted ? <CheckCircle className="h-4 w-4" /> : config.icon}
                    </div>
                    <div className="flex-1 pt-1">
                      <p className={`font-medium ${isCurrent ? "text-foreground" : isCompleted ? "text-foreground" : "text-muted-foreground"}`}>
                        {config.label}
                      </p>
                      <p className="text-sm text-muted-foreground">
                        {isCompleted && application.updated_at && `Updated ${new Date(application.updated_at).toLocaleDateString()}`}
                      </p>
                    </div>
                  </div>
                );
              })}
            </div>
          </CardContent>
        </Card>

        <div className="grid gap-6 md:grid-cols-2 lg:grid-cols-3">
          {/* Customer Info */}
          <Card>
            <CardHeader>
              <CardTitle className="flex items-center gap-2">
                <Users className="h-5 w-5" />
                Customer
              </CardTitle>
            </CardHeader>
            <CardContent className="space-y-3">
              <div>
                <Label className="text-xs text-muted-foreground">Name</Label>
                <p className="font-medium">{application.customer.name}</p>
              </div>
              <div>
                <Label className="text-xs text-muted-foreground">Mobile</Label>
                <p className="font-mono">{application.customer.mobile}</p>
              </div>
              {application.customer.email && (
                <div>
                  <Label className="text-xs text-muted-foreground">Email</Label>
                  <p>{application.customer.email}</p>
                </div>
              )}
              {application.customer.address && (
                <div>
                  <Label className="text-xs text-muted-foreground">Address</Label>
                  <p className="text-sm">{application.customer.address}</p>
                </div>
              )}
              <div className="pt-2 border-t">
                <Button variant="outline" size="sm" asChild>
                  <Link href={`/dashboard/customers/${application.customer.id}?shop_id=${shopId}`}>
                    View Customer Profile
                  </Link>
                </Button>
              </div>
            </CardContent>
          </Card>

          {/* Service Info */}
          <Card>
            <CardHeader>
              <CardTitle className="flex items-center gap-2">
                <Banknote className="h-5 w-5" />
                Service
              </CardTitle>
            </CardHeader>
            <CardContent className="space-y-3">
              <div>
                <Label className="text-xs text-muted-foreground">Name</Label>
                <p className="font-medium">{application.service.name}</p>
              </div>
              {application.service.description && (
                <div>
                  <Label className="text-xs text-muted-foreground">Description</Label>
                  <p className="text-sm">{application.service.description}</p>
                </div>
              )}
              <div>
                <Label className="text-xs text-muted-foreground">Base Price</Label>
                <p className="font-mono">{new Intl.NumberFormat("en-US", { style: "currency", currency: "USD" }).format(application.service.base_price)}</p>
              </div>
              <div className="pt-2 border-t">
                <Button variant="outline" size="sm" asChild>
                  <Link href={`/dashboard/services/${application.service.id}?shop_id=${shopId}`}>
                    View Service Details
                  </Link>
                </Button>
              </div>
            </CardContent>
          </Card>

          {/* Assigned Staff */}
          <Card>
            <CardHeader>
              <CardTitle className="flex items-center gap-2">
                <Users className="h-5 w-5" />
                Assigned Staff
              </CardTitle>
            </CardHeader>
            <CardContent>
              {application.assigned_staff ? (
                <div className="space-y-3">
                  <div className="flex items-center gap-3">
                    <div className="flex-shrink-0 h-10 w-10 rounded bg-muted/50 flex items-center justify-center">
                      <Users className="h-5 w-5 text-muted-foreground" />
                    </div>
                    <div>
                      <p className="font-medium">{application.assigned_staff.full_name}</p>
                      <p className="text-sm text-muted-foreground">{application.assigned_staff.email}</p>
                    </div>
                  </div>
                  {editMode && (
                    <div className="space-y-2">
                      <Label htmlFor="assigned_staff_id">Reassign Staff</Label>
                      <Select
                        value={formData.assigned_staff_id === "" ? "" : String(formData.assigned_staff_id)}
                        onValueChange={(v) => handleChange({ target: { name: "assigned_staff_id", value: v } } as any)}
                      >
                        <SelectTrigger>
                          <SelectValue placeholder="Select staff member" />
                        </SelectTrigger>
                        <SelectContent>
                          <SelectItem value="">Unassign</SelectItem>
                          {staff.map((s) => (
                            <SelectItem key={s.id} value={String(s.id)}>
                              {s.full_name} ({s.email})
                            </SelectItem>
                          ))}
                        </SelectContent>
                      </Select>
                    </div>
                  )}
                </div>
              ) : (
                <div className="space-y-3">
                  <p className="text-muted-foreground italic">No staff assigned</p>
                  {editMode && (
                    <div className="space-y-2">
                      <Label htmlFor="assigned_staff_id">Assign Staff</Label>
                      <Select
                        value={formData.assigned_staff_id === "" ? "" : String(formData.assigned_staff_id)}
                        onValueChange={(v) => handleChange({ target: { name: "assigned_staff_id", value: v } } as any)}
                      >
                        <SelectTrigger>
                          <SelectValue placeholder="Select staff member" />
                        </SelectTrigger>
                        <SelectContent>
                          {staff.map((s) => (
                            <SelectItem key={s.id} value={String(s.id)}>
                              {s.full_name} ({s.email})
                            </SelectItem>
                          ))}
                        </SelectContent>
                      </Select>
                    </div>
                  )}
                </div>
              )}
            </CardContent>
          </Card>

          {/* Application Data */}
          {application.service.fields && application.service.fields.length > 0 && (
            <Card className="md:col-span-2 lg:col-span-3">
              <CardHeader>
                <CardTitle>Service Information</CardTitle>
              </CardHeader>
              <CardContent className="space-y-4">
                {application.service.fields.map((field) => {
                  const value = application.application_data?.[field.name];
                  const displayValue = value === undefined || value === null || value === ""
                    ? <span className="text-muted-foreground italic">Not provided</span>
                    : field.field_type === "boolean"
                      ? (value ? "Yes" : "No")
                      : field.field_type === "date"
                        ? new Date(value).toLocaleDateString()
                        : String(value);

                  return (
                    <div key={field.id} className="space-y-1">
                      <Label className="text-xs text-muted-foreground">{field.label}</Label>
                      {editMode ? (
                        <div>
                          {field.field_type === "select" && field.options && field.options.length > 0 ? (
                            <Select
                              value={formData.application_data[field.name] === undefined ? "" : String(formData.application_data[field.name])}
                              onValueChange={(v) => handleDynamicFieldChange(field.name, v === "" ? undefined : v)}
                            >
                              <SelectTrigger>
                                <SelectValue placeholder={`Select ${field.label}`} />
                              </SelectTrigger>
                              <SelectContent>
                                <SelectItem value="">Select...</SelectItem>
                                {field.options.map((opt) => (
                                  <SelectItem key={opt} value={opt}>{opt}</SelectItem>
                                ))}
                              </SelectContent>
                            </Select>
                          ) : field.field_type === "boolean" ? (
                            <div className="flex items-center gap-2">
                              <input
                                type="checkbox"
                                id={`edit-${field.name}`}
                                checked={formData.application_data[field.name] === true}
                                onChange={(e) => handleDynamicFieldChange(field.name, e.target.checked)}
                                className="h-4 w-4 rounded border-gray-300 text-primary focus:ring-primary"
                              />
                              <Label htmlFor={`edit-${field.name}`} className="cursor-pointer mb-0">
                                {field.label === "Yes" ? "Yes" : "Enabled"}
                              </Label>
                            </div>
                          ) : field.field_type === "textarea" ? (
                            <Textarea
                              id={`edit-${field.name}`}
                              value={formData.application_data[field.name] || ""}
                              onChange={(e) => handleDynamicFieldChange(field.name, e.target.value)}
                              rows={3}
                            />
                          ) : field.field_type === "number" ? (
                            <Input
                              id={`edit-${field.name}`}
                              type="number"
                              value={formData.application_data[field.name] === undefined ? "" : String(formData.application_data[field.name])}
                              onChange={(e) => handleDynamicFieldChange(field.name, e.target.value === "" ? undefined : parseFloat(e.target.value))}
                            />
                          ) : field.field_type === "date" ? (
                            <Input
                              id={`edit-${field.name}`}
                              type="date"
                              value={formData.application_data[field.name] || ""}
                              onChange={(e) => handleDynamicFieldChange(field.name, e.target.value || undefined)}
                            />
                          ) : (
                            <Input
                              id={`edit-${field.name}`}
                              value={formData.application_data[field.name] || ""}
                              onChange={(e) => handleDynamicFieldChange(field.name, e.target.value || undefined)}
                            />
                          )}
                        </div>
                      ) : (
                        <p>{displayValue}</p>
                      )}
                    </div>
                  );
                })}
              </CardContent>
            </Card>
          )}

          {/* Notes */}
          <Card className="md:col-span-2 lg:col-span-3">
            <CardHeader>
              <CardTitle>Internal Notes</CardTitle>
            </CardHeader>
            <CardContent>
              {editMode ? (
                <div className="space-y-2">
                  <Label htmlFor="notes">Notes</Label>
                  <Textarea
                    id="notes"
                    value={formData.notes}
                    onChange={handleChange}
                    rows={4}
                    placeholder="Add internal notes..."
                  />
                </div>
              ) : (
                <p className={application.notes ? "" : "text-muted-foreground italic"}>
                  {application.notes || "No notes added"}
                </p>
              )}
            </CardContent>
          </Card>

          {/* Metadata */}
          <Card className="md:col-span-2 lg:col-span-3">
            <CardHeader>
              <CardTitle>Application Details</CardTitle>
            </CardHeader>
            <CardContent className="grid gap-4 sm:grid-cols-2">
              <div>
                <Label className="text-xs text-muted-foreground">Created</Label>
                <p>{new Date(application.created_at).toLocaleString()}</p>
              </div>
              <div>
                <Label className="text-xs text-muted-foreground">Last Updated</Label>
                <p>{new Date(application.updated_at).toLocaleString()}</p>
              </div>
              <div>
                <Label className="text-xs text-muted-foreground">Customer ID</Label>
                <p className="font-mono">{application.customer_id}</p>
              </div>
              <div>
                <Label className="text-xs text-muted-foreground">Service ID</Label>
                <p className="font-mono">{application.service_id}</p>
              </div>
            </CardContent>
          </Card>
        </div>

        {/* Document Management Section */}
        {shopId && application && (
          <div className="mt-8">
            <DocumentManager
              shopId={shopId}
              applicationId={application.id}
              canUpload={true}
              canVerify={true}
              canReject={true}
              canDelete={true}
              onChecklistUpdated={fetchApplication}
            />
          </div>
        )}

        {editMode && (
          <div className="mt-6 flex justify-end gap-3">
            <Button variant="outline" onClick={() => {
              setFormData({
                status: application.status,
                assigned_staff_id: application.assigned_staff_id || "",
                application_data: application.application_data || {},
                notes: application.notes || "",
              });
              setEditMode(false);
            }}>
              Cancel
            </Button>
            <Button onClick={handleSave} disabled={saving}>
              <Save className="mr-2 h-4 w-4" />
              {saving ? "Saving..." : "Save Changes"}
            </Button>
          </div>
        )}
      </div>
    </ProtectedRoute>
  );
}

export default function ApplicationDetailPage() {
  return <ApplicationDetailContent />;
}

input.content:
"use client";

import { useState, useEffect, useCallback } from "react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/components/ui/table";
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogTrigger } from "@/components/ui/dialog";
import { Separator } from "@/components/ui/separator";
import { formatCurrency } from "@/lib/utils";
import {
  Plus, Edit, Trash2, Save, X, Eye, Receipt, DollarSign,
  Minus, AlertCircle, CheckCircle, Loader2, CreditCard, Banknote,
  ArrowLeft, ArrowRight, RefreshCw, FileText, Shield, AlertTriangle,
  ChevronDown, ChevronUp
} from "lucide-react";
import {
  BillingResponse,
  BillingItemResponse,
  PaymentResponse,
  BillingItemCreate,
  BillingItemUpdate,
  PaymentCreate,
  PaymentFormData,
  PaymentMethod,
  BillingStatus,
  PaymentStatus,
  BillingFormData,
  PAYMENT_METHOD_LABELS,
  PAYMENT_STATUS_LABELS,
  BILLING_STATUS_LABELS,
  DISCOUNT_TYPE_LABELS,
  DiscountType,
  BillingCalculationPreview,
} from "@/src/types/billing";

interface BillingManagerProps {
  shopId: number;
  applicationId: number;
  applicationNumber: string;
  serviceName: string;
  serviceBasePrice: number;
  customerName: string;
  canCreate: boolean;
  canUpdate: boolean;
  canDiscount: boolean;
  canCharge: boolean;
  canVoid: boolean;
  canPaymentCreate: boolean;
  canPaymentView: boolean;
  onBillingCreated?: () => void;
}

export function BillingManager({
  shopId,
  applicationId,
  applicationNumber,
  serviceName,
  serviceBasePrice,
  customerName,
  canCreate,
  canUpdate,
  canDiscount,
  canCharge,
  canVoid,
  canPaymentCreate,
  canPaymentView,
  onBillingCreated,
}: BillingManagerProps) {
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [billing, setBilling] = useState<BillingResponse | null>(null);
  const [payments, setPayments] = useState<PaymentResponse[]>([]);
  const [saving, setSaving] = useState(false);
  const [creating, setCreating] = useState(false);
  const [creatingPayment, setCreatingPayment] = useState(false);
  const [showCreateDialog, setShowCreateDialog] = useState(false);
  const [showEditDialog, setShowEditDialog] = useState(false);
  const [showPaymentDialog, setShowPaymentDialog] = useState(false);
  const [showPreviewDialog, setShowPreviewDialog] = useState(false);
  const [editingItemId, setEditingItemId] = useState<number | null>(null);
  const [previewData, setPreviewData] = useState<BillingCalculationPreview | null>(null);

  // Form states
  const [createForm, setCreateForm] = useState<BillingFormData>({
    items: [
      {
        name: serviceName,
        description: `Service: ${serviceName}`,
        amount: serviceBasePrice,
        is_service_item: true,
        service_id: undefined,
        sort_order: 0,
      },
    ],
    discount_type: undefined,
    discount_value: undefined,
    discount_reason: "",
    notes: "",
  });

  const [editForm, setEditForm] = useState<Partial<BillingFormData>>({});

  const [itemForm, setItemForm] = useState<BillingItemCreate>({
    name: "",
    description: "",
    amount: 0,
    is_service_item: false,
    service_id: undefined,
    sort_order: 0,
  });

  const [paymentForm, setPaymentForm] = useState<PaymentFormData>({
    amount: 0,
    payment_method: "cash",
    reference_number: "",
    reference_exception: false,
    reference_exception_reason: "",
    notes: "",
  });

  const isDigitalPayment = (method: PaymentMethod) =>
    method !== "cash";

  const requiresReference = (method: PaymentMethod) =>
    isDigitalPayment(method);

  const fetchBilling = useCallback(async () => {
    setLoading(true);
    try {
      const response = await fetch(`/api/v1/shops/${shopId}/applications/${applicationId}/billing`, {
        headers: { "Authorization": `Bearer ${localStorage.getItem("access_token")}` },
      });
      if (response.ok) {
        const data = await response.json();
        setBilling(data);
      } else if (response.status === 404) {
        setBilling(null);
      } else {
        throw new Error("Failed to fetch billing");
      }
    } catch (err) {
      setError(err instanceof Error ? err.message : "An error occurred");
    } finally {
      setLoading(false);
    }
  }, [shopId, applicationId]);

  const fetchPayments = useCallback(async () => {
    if (!billing) return;
    try {
      const response = await fetch(`/api/v1/shops/${shopId}/applications/billing/${billing.id}/payments`, {
        headers: { "Authorization": `Bearer ${localStorage.getItem("access_token")}` },
      });
      if (response.ok) {
        const data = await response.json();
        setPayments(data.items || data);
      }
    } catch (err) {
      console.error("Failed to fetch payments:", err);
    }
  }, [shopId, billing]);

  useEffect(() => {
    fetchBilling();
  }, [fetchBilling]);

  useEffect(() => {
    fetchPayments();
  }, [fetchPayments]);

  const handlePreviewCalculation = async () => {
    if (createForm.items.length === 0) return;
    try {
      const response = await fetch(`/api/v1/shops/${shopId}/applications/billing/preview`, {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          "Authorization": `Bearer ${localStorage.getItem("access_token")}`,
        },
        body: JSON.stringify({
          items: createForm.items,
          discount_type: createForm.discount_type,
          discount_value: createForm.discount_value,
        }),
      });
      if (response.ok) {
        const data = await response.json();
        setPreviewData(data);
        setShowPreviewDialog(true);
      }
    } catch (err) {
      console.error("Failed to preview calculation:", err);
    }
  };

  const handleCreateBilling = async () => {
    if (createForm.items.length === 0) {
      setError("At least one line item is required");
      return;
    }
    if (createForm.discount_type && createForm.discount_value && !createForm.discount_reason) {
      setError("Discount reason is required");
      return;
    }
    setCreating(true);
    setError(null);
    try {
      const response = await fetch(`/api/v1/shops/${shopId}/applications/${applicationId}/billing`, {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          "Authorization": `Bearer ${localStorage.getItem("access_token")}`,
        },
        body: JSON.stringify({
          application_id: applicationId,
          ...createForm,
        }),
      });
      if (response.ok) {
        const data = await response.json();
        setBilling(data);
        setShowCreateDialog(false);
        onBillingCreated?.();
      } else {
        const data = await response.json();
        throw new Error(data.detail || "Failed to create billing");
      }
    } catch (err) {
      setError(err instanceof Error ? err.message : "An error occurred");
    } finally {
      setCreating(false);
    }
  };

  const handleUpdateBilling = async () => {
    if (!billing) return;
    setSaving(true);
    setError(null);
    try {
      const response = await fetch(`/api/v1/shops/${shopId}/applications/billing/${billing.id}`, {
        method: "PATCH",
        headers: {
          "Content-Type": "application/json",
          "Authorization": `Bearer ${localStorage.getItem("access_token")}`,
        },
        body: JSON.stringify(editForm),
      });
      if (response.ok) {
        const data = await response.json();
        setBilling(data);
        setShowEditDialog(false);
      } else {
        const data = await response.json();
        throw new Error(data.detail || "Failed to update billing");
      }
    } catch (err) {
      setError(err instanceof Error ? err.message : "An error occurred");
    } finally {
      setSaving(false);
    }
  };

  const handleAddItem = async () => {
    if (!billing || itemForm.name.trim() === "" || itemForm.amount <= 0) return;
    setSaving(true);
    try {
      const response = await fetch(`/api/v1/shops/${shopId}/applications/billing/${billing.id}/items`, {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          "Authorization": `Bearer ${localStorage.getItem("access_token")}`,
        },
        body: JSON.stringify(itemForm),
      });
      if (response.ok) {
        const data = await response.json();
        setBilling(prev => prev ? { ...prev, items: [...prev.items, data] } : null);
        setItemForm({ name: "", description: "", amount: 0, is_service_item: false, sort_order: 0 });
      } else {
        const data = await response.json();
        throw new Error(data.detail || "Failed to add item");
      }
    } catch (err) {
      setError(err instanceof Error ? err.message : "An error occurred");
    } finally {
      setSaving(false);
    }
  };

  const handleUpdateItem = async () => {
    if (!billing || editingItemId === null) return;
    setSaving(true);
    try {
      const response = await fetch(`/api/v1/shops/${shopId}/applications/billing/${billing.id}/items/${editingItemId}`, {
        method: "PATCH",
        headers: {
          "Content-Type": "application/json",
          "Authorization": `Bearer ${localStorage.getItem("access_token")}`,
        },
        body: JSON.stringify(itemForm),
      });
      if (response.ok) {
        const data = await response.json();
        setBilling(prev => prev ? {
          ...prev,
          items: prev.items.map(i => i.id === editingItemId ? data : i)
        } : null);
        setEditingItemId(null);
      } else {
        const data = await response.json();
        throw new Error(data.detail || "Failed to update item");
      }
    } catch (err) {
      setError(err instanceof Error ? err.message : "An error occurred");
    } finally {
      setSaving(false);
    }
  };

  const handleDeleteItem = async (itemId: number) => {
    if (!billing || !confirm("Delete this line item?")) return;
    setSaving(true);
    try {
      const response = await fetch(`/api/v1/shops/${shopId}/applications/billing/${billing.id}/items/${itemId}`, {
        method: "DELETE",
        headers: { "Authorization": `Bearer ${localStorage.getItem("access_token")}` },
      });
      if (response.ok) {
        setBilling(prev => prev ? { ...prev, items: prev.items.filter(i => i.id !== itemId) } : null);
      } else {
        const data = await response.json();
        throw new Error(data.detail || "Failed to delete item");
      }
    } catch (err) {
      setError(err instanceof Error ? err.message : "An error occurred");
    } finally {
      setSaving(false);
    }
  };

  const startEditItem = (item: BillingItemResponse) => {
    setItemForm({
      name: item.name,
      description: item.description || "",
      amount: item.amount,
      is_service_item: item.is_service_item,
      service_id: item.service_id,
      sort_order: item.sort_order,
    });
    setEditingItemId(item.id);
  };

  const handleCreatePayment = async () => {
    if (!billing) return;
    if (paymentForm.amount <= 0) {
      setError("Payment amount must be greater than zero");
      return;
    }
    if (paymentForm.amount > (billing.balance_amount || 0)) {
      setError("Payment amount exceeds outstanding balance");
      return;
    }
    if (requiresReference(paymentForm.payment_method) && !paymentForm.reference_exception && !paymentForm.reference_number?.trim()) {
      setError("Reference number is required for digital payments");
      return;
    }
    if (paymentForm.reference_exception && !paymentForm.reference_exception_reason?.trim()) {
      setError("Exception reason is required when reference is unavailable");
      return;
    }
    setCreatingPayment(true);
    setError(null);
    try {
      const response = await fetch(`/api/v1/shops/${shopId}/applications/billing/${billing.id}/payments`, {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          "Authorization": `Bearer ${localStorage.getItem("access_token")}`,
        },
        body: JSON.stringify(paymentForm),
      });
      if (response.ok) {
        const data = await response.json();
        setPayments(prev => [...prev, data]);
        setBilling(prev => prev ? {
          ...prev,
          amount_paid: data.amount + (prev.amount_paid || 0),
          balance_amount: Math.max(0, (prev.balance_amount || 0) - data.amount),
          payment_status: data.amount + (prev.amount_paid || 0) >= (prev.total_amount || 0) ? "paid" :
            data.amount + (prev.amount_paid || 0) > 0 ? "partially_paid" : "unpaid",
        } : null);
        setShowPaymentDialog(false);
        setPaymentForm({ amount: 0, payment_method: "cash", reference_number: "", reference_exception: false, reference_exception_reason: "", notes: "" });
      } else {
        const data = await response.json();
        throw new Error(data.detail || "Failed to record payment");
      }
    } catch (err) {
      setError(err instanceof Error ? err.message : "An error occurred");
    } finally {
      setCreatingPayment(false);
    }
  };

  const handleIssueBilling = async () => {
    if (!billing || !confirm("Issue this billing? This will change status from Draft to Issued.")) return;
    setSaving(true);
    try {
      const response = await fetch(`/api/v1/shops/${shopId}/applications/billing/${billing.id}/issue`, {
        method: "POST",
        headers: { "Authorization": `Bearer ${localStorage.getItem("access_token")}` },
      });
      if (response.ok) {
        const data = await response.json();
        setBilling(data);
      } else {
        const data = await response.json();
        throw new Error(data.detail || "Failed to issue billing");
      }
    } catch (err) {
      setError(err instanceof Error ? err.message : "An error occurred");
    } finally {
      setSaving(false);
    }
  };

  const handleVoidBilling = async () => {
    if (!billing || !confirm("Void this billing? This action cannot be undone.")) return;
    setSaving(true);
    try {
      const response = await fetch(`/api/v1/shops/${shopId}/applications/billing/${billing.id}/void`, {
        method: "POST",
        headers: { "Authorization": `Bearer ${localStorage.getItem("access_token")}` },
      });
      if (response.ok) {
        const data = await response.json();
        setBilling(data);
      } else {
        const data = await response.json();
        throw new Error(data.detail || "Failed to void billing");
      }
    } catch (err) {
      setError(err instanceof Error ? err.message : "An error occurred");
    } finally {
      setSaving(false);
    }
  };

  const getStatusBadge = (status: string, type: "billing" | "payment") => {
    if (type === "billing") {
      const config: Record<BillingStatus, { variant: "default" | "secondary" | "destructive" | "outline" | "success" | "warning" | "info"; label: string }> = {
        draft: { variant: "secondary", label: "Draft" },
        issued: { variant: "default", label: "Issued" },
        void: { variant: "destructive", label: "Void" },
      };
      const c = config[status as BillingStatus] || { variant: "secondary", label: status };
      return <Badge variant={c.variant}>{c.label}</Badge>;
    } else {
      const config: Record<PaymentStatus, { variant: "default" | "secondary" | "destructive" | "outline" | "success" | "warning" | "info"; label: string }> = {
        unpaid: { variant: "destructive", label: "Unpaid" },
        partially_paid: { variant: "warning", label: "Partially Paid" },
        paid: { variant: "success", label: "Paid" },
      };
      const c = config[status as PaymentStatus] || { variant: "secondary", label: status };
      return <Badge variant={c.variant}>{c.label}</Badge>;
    }
  };

  const paymentMethodLabel = (method: PaymentMethod) =>
    PAYMENT_METHOD_LABELS.find(l => l.value === method)?.label || method;

  const isDigital = (method: PaymentMethod) => isDigitalPayment(method);

  if (loading) {
    return (
      <Card className="mt-6">
        <CardContent className="py-8 text-center">
          <Loader2 className="h-8 w-8 animate-spin text-primary mx-auto mb-2" />
          <p className="text-muted-foreground">Loading billing...</p>
        </CardContent>
      </Card>
    );
  }

  if (error) {
    return (
      <Card className="mt-6 border-destructive">
        <CardContent className="p-4 text-destructive">
          <AlertCircle className="h-5 w-5 mr-2 inline" />
          {error}
        </CardContent>
      </Card>
    );
  }

  if (!billing) {
    if (!canCreate) {
      return (
        <Card className="mt-6">
          <CardContent className="py-8 text-center">
            <FileText className="h-12 w-12 text-muted-foreground mx-auto mb-4" />
            <h3 className="text-lg font-medium mb-2">No Billing Record</h3>
            <p className="text-muted-foreground mb-4">Create a billing record to track payments for this application.</p>
          </CardContent>
        </Card>
      );
    }

    return (
      <Card className="mt-6">
        <CardHeader>
          <CardTitle className="flex items-center gap-2">
            <DollarSign className="h-5 w-5" />
            Create Billing for {applicationNumber}
          </CardTitle>
          <CardDescription>Set up invoice with service amount, additional charges, and discounts</CardDescription>
        </CardHeader>
        <CardContent className="space-y-6">
          {/* Service Item (non-editable price) */}
          <div className="bg-muted/50 p-4 rounded-lg border">
            <div className="flex items-center gap-2 text-sm text-muted-foreground mb-2">
              <Shield className="h-4 w-4" />
              <span>Service price is loaded from service configuration and cannot be freely edited</span>
            </div>
            <div className="grid gap-4 sm:grid-cols-3">
              <div className="sm:col-span-2">
                <Label className="text-xs text-muted-foreground">Service</Label>
                <Input value={serviceName} disabled />
              </div>
              <div>
                <Label className="text-xs text-muted-foreground">Base Price</Label>
                <Input value={formatCurrency(serviceBasePrice)} disabled />
              </div>
            </div>
          </div>

          {/* Line Items */}
          <div>
            <div className="flex items-center justify-between mb-3">
              <Label>Line Items</Label>
              <Dialog open={showCreateDialog} onOpenChange={setShowCreateDialog}>
                <DialogTrigger asChild>
                  <Button size="sm"><Plus className="h-4 w-4 mr-1" /> Add Charge</Button>
                </DialogTrigger>
                <DialogContent>
                  <DialogHeader>
                    <DialogTitle>Add Additional Charge</DialogTitle>
                  </DialogHeader>
                  <div className="space-y-4 py-4">
                    <div className="space-y-2">
                      <Label htmlFor="item-name">Charge Name</Label>
                      <Input
                        id="item-name"
                        value={itemForm.name}
                        onChange={e => setItemForm(prev => ({ ...prev, name: e.target.value }))}
                        placeholder="e.g., Printing, Courier, Service Fee"
                      />
                    </div>
                    <div className="space-y-2">
                      <Label htmlFor="item-description">Description (Optional)</Label>
                      <Textarea
                        id="item-description"
                        value={itemForm.description}
                        onChange={e => setItemForm(prev => ({ ...prev, description: e.target.value }))}
                        rows={2}
                      />
                    </div>
                    <div className="grid gap-4 sm:grid-cols-2">
                      <div className="space-y-2">
                        <Label htmlFor="item-amount">Amount</Label>
                        <Input
                          id="item-amount"
                          type="number"
                          step="0.01"
                          min="0"
                          value={itemForm.amount}
                          onChange={e => setItemForm(prev => ({ ...prev, amount: parseFloat(e.target.value) || 0 }))}
                        />
                      </div>
                      <div className="space-y-2">
                        <Label>Type</Label>
                        <Select value={itemForm.is_service_item ? "service" : "charge"} onValueChange={v => setItemForm(prev => ({ ...prev, is_service_item: v === "service" }))}>
                          <SelectTrigger><SelectValue placeholder="Select type" /></SelectTrigger>
                          <SelectContent>
                            <SelectItem value="charge">Non-Service Charge</SelectItem>
                            <SelectItem value="service">Service Item</SelectItem>
                          </SelectContent>
                        </Select>
                      </div>
                    </div>
                    <div className="flex justify-end gap-2 pt-4 border-t">
                      <Button variant="outline" onClick={() => { setShowCreateDialog(false); setItemForm({ name: "", description: "", amount: 0, is_service_item: false, sort_order: 0 }); }}>Cancel</Button>
                      <Button onClick={handleAddItem} disabled={saving || itemForm.name.trim() === "" || itemForm.amount <= 0}>{saving ? <Loader2 className="h-4 w-4 animate-spin" /> : "Add"}</Button>
                    </div>
                  </div>
                </DialogContent>
              </Dialog>
            </div>
            {createForm.items.map((item, index) => (
              <div key={index} className="flex items-center gap-3 p-3 border rounded-lg bg-background mb-2">
                <div className="flex-1 min-w-0">
                  <p className="font-medium">{item.name} {item.is_service_item && <Badge variant="secondary" className="ml-2 text-xs">Service</Badge>}</p>
                  {item.description && <p className="text-sm text-muted-foreground">{item.description}</p>}
                </div>
                <div className="font-mono text-right whitespace-nowrap">{formatCurrency(item.amount)}</div>
                {index > 0 && (
                  <Button variant="ghost" size="icon" onClick={() => {
                    const newItems = [...createForm.items];
                    newItems.splice(index, 1);
                    setCreateForm(prev => ({ ...prev, items: newItems }));
                  }}><Trash2 className="h-4 w-4 text-destructive" /></Button>
                )}
              </div>
            ))}
          </div>

          {/* Discount */}
          <div>
            <Label>Discount</Label>
            <div className="grid gap-4 sm:grid-cols-3">
              <div className="space-y-2">
                <Label htmlFor="discount-type">Type</Label>
                <Select value={createForm.discount_type || ""} onValueChange={v => setCreateForm(prev => ({ ...prev, discount_type: v as DiscountType || undefined }))}>
                  <SelectTrigger><SelectValue placeholder="Select discount type" /></SelectTrigger>
                  <SelectContent>
                    <SelectItem value="fixed">Fixed Amount</SelectItem>
                    <SelectItem value="percentage">Percentage</SelectItem>
                  </SelectContent>
                </Select>
              </div>
              <div className="space-y-2">
                <Label htmlFor="discount-value">Value</Label>
                <Input
                  id="discount-value"
                  type="number"
                  step="0.01"
                  min="0"
                  value={createForm.discount_value || ""}
                  onChange={e => setCreateForm(prev => ({ ...prev, discount_value: parseFloat(e.target.value) || undefined }))}
                  placeholder={createForm.discount_type === "percentage" ? "e.g., 10" : "e.g., 50"}
                />
              </div>
              <div className="space-y-2">
                <Label htmlFor="discount-reason">Reason (Required)</Label>
                <Input
                  id="discount-reason"
                  value={createForm.discount_reason}
                  onChange={e => setCreateForm(prev => ({ ...prev, discount_reason: e.target.value }))}
                  placeholder="e.g., Student discount, Loyalty, Manager approval"
                />
              </div>
            </div>
          </div>

          {/* Notes */}
          <div className="space-y-2">
            <Label htmlFor="notes">Internal Notes</Label>
            <Textarea
              id="notes"
              value={createForm.notes}
              onChange={e => setCreateForm(prev => ({ ...prev, notes: e.target.value }))}
              rows={3}
              placeholder="Optional internal notes..."
            />
          </div>

          {/* Preview & Create */}
          <div className="flex gap-3 pt-4 border-t">
            <Button variant="outline" onClick={handlePreviewCalculation}><Eye className="h-4 w-4 mr-1" /> Preview</Button>
            <Button onClick={handleCreateBilling} disabled={creating} className="ml-auto">
              {creating ? <Loader2 className="h-4 w-4 animate-spin" /> : "Create Billing"}
            </Button>
          </div>
        </CardContent>
      </Card>
    );
  }

  // Render existing billing
  return (
    <div className="mt-6 space-y-6">
      {/* Billing Header */}
      <Card>
        <CardHeader>
          <div className="flex items-center justify-between">
            <div>
              <CardTitle className="flex items-center gap-2">
                <DollarSign className="h-5 w-5" />
                Billing: {billing.invoice_number}
              </CardTitle>
              <CardDescription>Application: {applicationNumber} | Service: {serviceName} | Customer: {customerName}</CardDescription>
            </div>
            <div className="flex items-center gap-2">
              {getStatusBadge(billing.billing_status, "billing")}
              {getStatusBadge(billing.payment_status, "payment")}
            </div>
          </div>
        </CardHeader>
        <CardContent className="space-y-6">
          {/* Summary */}
          <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-4">
            <div className="p-4 bg-muted/50 rounded-lg">
              <Label className="text-xs text-muted-foreground">Subtotal</Label>
              <p className="text-2xl font-bold">{formatCurrency(billing.subtotal)}</p>
            </div>
            <div className="p-4 bg-muted/50 rounded-lg">
              <Label className="text-xs text-muted-foreground">Discount</Label>
              <p className="text-2xl font-bold text-green-600">-{formatCurrency(billing.discount_amount)}</p>
            </div>
            <div className="p-4 bg-primary/10 rounded-lg border border-primary/20">
              <Label className="text-xs text-muted-foreground">Total</Label>
              <p className="text-2xl font-bold text-primary">{formatCurrency(billing.total_amount)}</p>
            </div>
            <div className="p-4 bg-green-50 rounded-lg border border-green-200">
              <Label className="text-xs text-muted-foreground">Paid</Label>
              <p className="text-2xl font-bold text-green-600">{formatCurrency(billing.amount_paid)}</p>
            </div>
          </div>

          <Separator />

          {/* Balance */}
          <div className="grid gap-4 sm:grid-cols-2">
            <div className="p-4 bg-amber-50 rounded-lg border border-amber-200">
              <Label className="text-xs text-muted-foreground">Balance Due</Label>
              <p className="text-2xl font-bold text-amber-600">{formatCurrency(billing.balance_amount)}</p>
            </div>
            <div className="p-4 bg-muted/50 rounded-lg">
              <Label className="text-xs text-muted-foreground">Status</Label>
              <div className="flex items-center gap-2">
                {getStatusBadge(billing.payment_status, "payment")}
              </div>
            </div>
          </div>

          {/* Line Items Table */}
          <div>
            <div className="flex items-center justify-between mb-3">
              <Label>Line Items</Label>
              {canCharge && billing.billing_status === "draft" && billing.amount_paid === 0 && (
                <Dialog open={showCreateDialog} onOpenChange={setShowCreateDialog}>
                  <DialogTrigger asChild>
                    <Button size="sm" variant="outline"><Plus className="h-4 w-4 mr-1" /> Add Charge</Button>
                  </DialogTrigger>
                  <DialogContent>
                    <DialogHeader>
                      <DialogTitle>Add Additional Charge</DialogTitle>
                    </DialogHeader>
                    <div className="space-y-4 py-4">
                      <div className="space-y-2">
                        <Label htmlFor="item-name">Charge Name</Label>
                        <Input
                          id="item-name"
                          value={itemForm.name}
                          onChange={e => setItemForm(prev => ({ ...prev, name: e.target.value }))}
                          placeholder="e.g., Printing, Courier, Service Fee"
                        />
                      </div>
                      <div className="space-y-2">
                        <Label htmlFor="item-description">Description (Optional)</Label>
                        <Textarea
                          id="item-description"
                          value={itemForm.description}
                          onChange={e => setItemForm(prev => ({ ...prev, description: e.target.value }))}
                          rows={2}
                        />
                      </div>
                      <div className="grid gap-4 sm:grid-cols-2">
                        <div className="space-y-2">
                          <Label htmlFor="item-amount">Amount</Label>
                          <Input
                            id="item-amount"
                            type="number"
                            step="0.01"
                            min="0"
                            value={itemForm.amount}
                            onChange={e => setItemForm(prev => ({ ...prev, amount: parseFloat(e.target.value) || 0 }))}
                          />
                        </div>
                        <div className="space-y-2">
                          <Label>Type</Label>
                          <Select value={itemForm.is_service_item ? "service" : "charge"} onValueChange={v => setItemForm(prev => ({ ...prev, is_service_item: v === "service" }))}>
                            <SelectTrigger><SelectValue placeholder="Select type" /></SelectTrigger>
                            <SelectContent>
                              <SelectItem value="charge">Non-Service Charge</SelectItem>
                              <SelectItem value="service">Service Item</SelectItem>
                            </SelectContent>
                          </Select>
                        </div>
                      </div>
                      <div className="flex justify-end gap-2 pt-4 border-t">
                        <Button variant="outline" onClick={() => { setShowCreateDialog(false); setItemForm({ name: "", description: "", amount: 0, is_service_item: false, sort_order: 0 }); }}>Cancel</Button>
                        <Button onClick={handleAddItem} disabled={saving || itemForm.name.trim() === "" || itemForm.amount <= 0}>{saving ? <Loader2 className="h-4 w-4 animate-spin" /> : "Add"}</Button>
                      </div>
                    </div>
                  </DialogContent>
                </Dialog>
              )}
            </div>
            <div className="overflow-x-auto">
              <Table>
                <TableHeader>
                  <TableRow>
                    <TableHead>Item</TableHead>
                    <TableHead className="text-right">Amount</TableHead>
                    <TableHead className="text-center">Type</TableHead>
                    {billing.billing_status === "draft" && billing.amount_paid === 0 && canCharge && <TableHead className="text-center">Actions</TableHead>}
                  </TableRow>
                </TableHeader>
                <TableBody>
                  {billing.items.map((item) => (
                    <TableRow key={item.id}>
                      <TableCell>
                        <div>
                          <p className="font-medium">{item.name}</p>
                          {item.description && <p className="text-sm text-muted-foreground">{item.description}</p>}
                        </div>
                      </TableCell>
                      <TableCell className="font-mono text-right">{formatCurrency(item.amount)}</TableCell>
                      <TableCell className="text-center">
                        <Badge variant={item.is_service_item ? "secondary" : "outline"}>
                          {item.is_service_item ? "Service" : "Charge"}
                        </Badge>
                      </TableCell>
                      {billing.billing_status === "draft" && billing.amount_paid === 0 && canCharge && (
                        <TableCell className="text-center">
                          <div className="flex items-center justify-center gap-1">
                            <Button variant="ghost" size="icon" onClick={() => startEditItem(item)}><Edit className="h-4 w-4" /></Button>
                            <Button variant="ghost" size="icon" onClick={() => handleDeleteItem(item.id)}><Trash2 className="h-4 w-4 text-destructive" /></Button>
                          </div>
                        </TableCell>
                      )}
                    </TableRow>
                  ))}
                </TableBody>
              </Table>
            </div>
          </div>

          {/* Discount Display */}
          {billing.discount_amount > 0 && (
            <div className="bg-green-50 border border-green-200 rounded-lg p-4">
              <div className="flex items-center justify-between">
                <div className="flex items-center gap-2">
                  <AlertCircle className="h-5 w-5 text-green-600" />
                  <div>
                    <p className="font-medium">Discount Applied</p>
                    <p className="text-sm text-green-700">
                      {DISCOUNT_TYPE_LABELS[billing.discount_type as DiscountType] || billing.discount_type}: {billing.discount_value}
                      {billing.discount_type === "percentage" ? "%" : formatCurrency(billing.discount_value || 0)}
                    </p>
                  </div>
                </div>
                <div className="font-mono text-green-600">-{formatCurrency(billing.discount_amount)}</div>
              </div>
              {billing.discount_reason && (
                <p className="mt-2 text-sm text-green-700"><strong>Reason:</strong> {billing.discount_reason}</p>
              )}
            </div>
          )}

          {/* Notes */}
          {billing.notes && (
            <div className="bg-muted/50 rounded-lg p-4">
              <Label className="text-xs text-muted-foreground">Notes</Label>
              <p>{billing.notes}</p>
            </div>
          )}

          {/* Actions */}
          <div className="flex flex-wrap gap-3 pt-4 border-t">
            {canUpdate && billing.billing_status === "draft" && billing.amount_paid === 0 && (
              <Button variant="outline" onClick={() => {
                setEditForm({
                  notes: billing.notes,
                  discount_type: billing.discount_type,
                  discount_value: billing.discount_value,
                  discount_reason: billing.discount_reason,
                });
                setShowEditDialog(true);
              }}>
                <Edit className="h-4 w-4 mr-1" /> Edit Details
              </Button>
            )}
            {canVoid && billing.billing_status !== "void" && billing.amount_paid === 0 && (
              <Button variant="destructive" onClick={handleVoidBilling} disabled={saving}>
                <Shield className="h-4 w-4 mr-1" /> Void Billing
              </Button>
            )}
            {billing.billing_status === "draft" && (
              <Button variant="secondary" onClick={handleIssueBilling} disabled={saving}>
                <FileText className="h-4 w-4 mr-1" /> Issue Billing
              </Button>
            )}
            {canPaymentCreate && billing.balance_amount > 0 && billing.billing_status !== "void" && (
              <Button onClick={() => setShowPaymentDialog(true)}>
                <CreditCard className="h-4 w-4 mr-1" /> Record Payment
              </Button>
            )}
            {canPaymentView && payments.length > 0 && (
              <Button variant="outline" asChild>
                <a href={`/dashboard/applications/${applicationId}/billing/${billing.id}/receipt`} target="_blank" rel="noopener noreferrer">
                  <Receipt className="h-4 w-4 mr-1" /> View Receipt
                </a>
              </Button>
            )}
          </div>
        </CardContent>
      </Card>

      {/* Payments History */}
      {canPaymentView && (
        <Card>
          <CardHeader>
            <CardTitle className="flex items-center gap-2">
              <Banknote className="h-5 w-5" />
              Payment History ({payments.length})
            </CardTitle>
          </CardHeader>
          <CardContent>
            {payments.length === 0 ? (
              <p className="text-muted-foreground text-center py-8">No payments recorded yet.</p>
            ) : (
              <div className="overflow-x-auto">
                <Table>
                  <TableHeader>
                    <TableRow>
                      <TableHead>Date</TableHead>
                      <TableHead>Amount</TableHead>
                      <TableHead>Method</TableHead>
                      <TableHead>Reference</TableHead>
                      <TableHead>Recorded By</TableHead>
                    </TableRow>
                  </TableHeader>
                  <TableBody>
                    {payments.map((payment) => (
                      <TableRow key={payment.id}>
                        <TableCell>{new Date(payment.paid_at).toLocaleString()}</TableCell>
                        <TableCell className="font-mono">{formatCurrency(payment.amount)}</TableCell>
                        <TableCell>
                          <Badge variant="outline">{paymentMethodLabel(payment.payment_method)}</Badge>
                        </TableCell>
                        <TableCell>
                          {payment.reference_exception ? (
                            <span className="text-sm text-amber-600">Exception: {payment.reference_exception_reason}</span>
                          ) : (
                            payment.reference_number || <span className="text-muted-foreground">—</span>
                          )}
                        </TableCell>
                        <TableCell>{payment.recorder_name || payment.recorded_by}</TableCell>
                      </TableRow>
                    ))}
                  </TableBody>
                </Table>
              </div>
            )}
          </CardContent>
        </Card>
      )}

      {/* Edit Billing Dialog */}
      {showEditDialog && billing && (
        <Dialog open={showEditDialog} onOpenChange={setShowEditDialog}>
          <DialogContent className="max-w-2xl">
            <DialogHeader>
              <DialogTitle>Edit Billing Details</DialogTitle>
            </DialogHeader>
            <div className="space-y-4 py-4">
              <div className="space-y-2">
                <Label htmlFor="edit-notes">Notes</Label>
                <Textarea
                  id="edit-notes"
                  value={editForm.notes || ""}
                  onChange={e => setEditForm(prev => ({ ...prev, notes: e.target.value }))}
                  rows={3}
                />
              </div>
              <div className="grid gap-4 sm:grid-cols-3">
                <div className="space-y-2">
                  <Label htmlFor="edit-discount-type">Discount Type</Label>
                  <Select value={editForm.discount_type || ""} onValueChange={v => setEditForm(prev => ({ ...prev, discount_type: v as DiscountType || undefined }))}>
                    <SelectTrigger><SelectValue placeholder="Select type" /></SelectTrigger>
                    <SelectContent>
                      <SelectItem value="fixed">Fixed Amount</SelectItem>
                      <SelectItem value="percentage">Percentage</SelectItem>
                    </SelectContent>
                  </Select>
                </div>
                <div className="space-y-2">
                  <Label htmlFor="edit-discount-value">Discount Value</Label>
                  <Input
                    id="edit-discount-value"
                    type="number"
                    step="0.01"
                    min="0"
                    value={editForm.discount_value || ""}
                    onChange={e => setEditForm(prev => ({ ...prev, discount_value: parseFloat(e.target.value) || undefined }))}
                  />
                </div>
                <div className="space-y-2">
                  <Label htmlFor="edit-discount-reason">Reason</Label>
                  <Input
                    id="edit-discount-reason"
                    value={editForm.discount_reason || ""}
                    onChange={e => setEditForm(prev => ({ ...prev, discount_reason: e.target.value }))}
                  />
                </div>
              </div>
              <div className="flex justify-end gap-2 pt-4 border-t">
                <Button variant="outline" onClick={() => setShowEditDialog(false)}>Cancel</Button>
                <Button onClick={handleUpdateBilling} disabled={saving}>{saving ? <Loader2 className="h-4 w-4 animate-spin" /> : "Save Changes"}</Button>
              </div>
            </div>
          </DialogContent>
        </Dialog>
      )}

      {/* Payment Dialog */}
      {showPaymentDialog && billing && (
        <Dialog open={showPaymentDialog} onOpenChange={setShowPaymentDialog}>
          <DialogContent className="max-w-lg">
            <DialogHeader>
              <DialogTitle>Record Payment</DialogTitle>
            </DialogHeader>
            <div className="space-y-4 py-4">
              {/* Balance Info */}
              <div className="bg-muted/50 p-4 rounded-lg">
                <div className="grid gap-2 sm:grid-cols-3 text-sm">
                  <div><Label className="text-muted-foreground">Invoice Total</Label> <p className="font-mono">{formatCurrency(billing.total_amount)}</p></div>
                  <div><Label className="text-muted-foreground">Already Paid</Label> <p className="font-mono text-green-600">{formatCurrency(billing.amount_paid)}</p></div>
                  <div><Label className="text-muted-foreground">Balance Due</Label> <p className="font-mono text-amber-600">{formatCurrency(billing.balance_amount)}</p></div>
                </div>
              </div>

              <div className="space-y-2">
                <Label htmlFor="payment-amount">Amount <span className="text-destructive">*</span></Label>
                <Input
                  id="payment-amount"
                  type="number"
                  step="0.01"
                  min="0.01"
                  max={billing.balance_amount}
                  value={paymentForm.amount}
                  onChange={e => setPaymentForm(prev => ({ ...prev, amount: parseFloat(e.target.value) || 0 }))}
                />
              </div>

              <div className="space-y-2">
                <Label htmlFor="payment-method">Payment Method <span className="text-destructive">*</span></Label>
                <Select value={paymentForm.payment_method} onValueChange={v => setPaymentForm(prev => ({ ...prev, payment_method: v as PaymentMethod }))}>
                  <SelectTrigger><SelectValue placeholder="Select payment method" /></SelectTrigger>
                  <SelectContent>
                    {PAYMENT_METHOD_LABELS.map(m => (
                      <SelectItem key={m.value} value={m.value}>{m.label}</SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              </div>

              {isDigital(paymentForm.payment_method) && !paymentForm.reference_exception && (
                <div className="space-y-2">
                  <Label htmlFor="payment-reference">Reference Number <span className="text-destructive">*</span></Label>
                  <Input
                    id="payment-reference"
                    value={paymentForm.reference_number}
                    onChange={e => setPaymentForm(prev => ({ ...prev, reference_number: e.target.value }))}
                    placeholder={paymentForm.payment_method === "upi" ? "UPI Transaction ID" : paymentForm.payment_method === "card" ? "Card Transaction ID" : "Reference Number"}
                  />
                </div>
              )}

              <div className="space-y-2">
                <Label className="flex items-center gap-2">
                  <input
                    type="checkbox"
                    checked={paymentForm.reference_exception}
                    onChange={e => setPaymentForm(prev => ({ ...prev, reference_exception: e.target.checked, reference_number: e.target.checked ? "" : prev.reference_number }))}
                    className="h-4 w-4 rounded border-gray-300 text-primary focus:ring-primary"
                  />
                  Reference number not available
                </Label>
              </div>

              {paymentForm.reference_exception && (
                <div className="space-y-2">
                  <Label htmlFor="payment-exception-reason">Exception Reason <span className="text-destructive">*</span></Label>
                  <Textarea
                    id="payment-exception-reason"
                    value={paymentForm.reference_exception_reason}
                    onChange={e => setPaymentForm(prev => ({ ...prev, reference_exception_reason: e.target.value }))}
                    rows={2}
                    placeholder="e.g., Customer didn't provide it, Reference number unavailable, Payment verified manually"
                  />
                </div>
              )}

              <div className="space-y-2">
                <Label htmlFor="payment-notes">Notes</Label>
                <Textarea
                  id="payment-notes"
                  value={paymentForm.notes}
                  onChange={e => setPaymentForm(prev => ({ ...prev, notes: e.target.value }))}
                  rows={2}
                />
              </div>

              <div className="flex justify-end gap-2 pt-4 border-t">
                <Button variant="outline" onClick={() => { setShowPaymentDialog(false); setPaymentForm({ amount: 0, payment_method: "cash", reference_number: "", reference_exception: false, reference_exception_reason: "", notes: "" }); }}>Cancel</Button>
                <Button onClick={handleCreatePayment} disabled={creatingPayment}>{creatingPayment ? <Loader2 className="h-4 w-4 animate-spin" /> : "Record Payment"}</Button>
              </div>
            </div>
          </DialogContent>
        </Dialog>
      )}

      {/* Preview Dialog */}
      {showPreviewDialog && previewData && (
        <Dialog open={showPreviewDialog} onOpenChange={setShowPreviewDialog}>
          <DialogContent className="max-w-md">
            <DialogHeader>
              <DialogTitle>Billing Calculation Preview</DialogTitle>
            </DialogHeader>
            <div className="space-y-3 py-4">
              <div className="flex justify-between"><span>Service Amount</span> <span className="font-mono">{formatCurrency(previewData.service_amount)}</span></div>
              <div className="flex justify-between"><span>Additional Charges</span> <span className="font-mono">{formatCurrency(previewData.non_service_charges)}</span></div>
              <Separator />
              <div className="flex justify-between"><span>Subtotal</span> <span className="font-mono font-medium">{formatCurrency(previewData.subtotal)}</span></div>
              {previewData.discount_type && (
                <>
                  <div className="flex justify-between text-green-600">
                    <span>Discount ({DISCOUNT_TYPE_LABELS[previewData.discount_type]}: {previewData.discount_value}{previewData.discount_type === "percentage" ? "%" : ""})</span>
                    <span className="font-mono">-{formatCurrency(previewData.discount_amount)}</span>
                  </div>
                  <Separator />
                </>
              )}
              <div className="flex justify-between text-lg font-bold">
                <span>Total</span> <span className="font-mono text-primary">{formatCurrency(previewData.total_amount)}</span>
              </div>
            </div>
            <div className="flex justify-end pt-4 border-t">
              <Button onClick={() => setShowPreviewDialog(false)}>Close</Button>
            </div>
          </DialogContent>
        </Dialog>
      )}

      {/* Edit Item Dialog */}
      {editingItemId !== null && billing && (
        <Dialog open={true} onOpenChange={setEditingItemId}>
          <DialogContent>
            <DialogHeader>
              <DialogTitle>Edit Line Item</DialogTitle>
            </DialogHeader>
            <div className="space-y-4 py-4">
              <div className="space-y-2">
                <Label htmlFor="edit-item-name">Name</Label>
                <Input
                  id="edit-item-name"
                  value={itemForm.name}
                  onChange={e => setItemForm(prev => ({ ...prev, name: e.target.value }))}
                />
              </div>
              <div className="space-y-2">
                <Label htmlFor="edit-item-description">Description</Label>
                <Textarea
                  id="edit-item-description"
                  value={itemForm.description}
                  onChange={e => setItemForm(prev => ({ ...prev, description: e.target.value }))}
                  rows={2}
                />
              </div>
              <div className="grid gap-4 sm:grid-cols-2">
                <div className="space-y-2">
                  <Label htmlFor="edit-item-amount">Amount</Label>
                  <Input
                    id="edit-item-amount"
                    type="number"
                    step="0.01"
                    min="0"
                    value={itemForm.amount}
                    onChange={e => setItemForm(prev => ({ ...prev, amount: parseFloat(e.target.value) || 0 }))}
                  />
                </div>
                <div className="space-y-2">
                  <Label>Type</Label>
                  <Select value={itemForm.is_service_item ? "service" : "charge"} onValueChange={v => setItemForm(prev => ({ ...prev, is_service_item: v === "service" }))}>
                    <SelectTrigger><SelectValue placeholder="Select type" /></SelectTrigger>
                    <SelectContent>
                      <SelectItem value="charge">Non-Service Charge</SelectItem>
                      <SelectItem value="service">Service Item</SelectItem>
                    </SelectContent>
                  </Select>
                </div>
              </div>
              <div className="flex justify-end gap-2 pt-4 border-t">
                <Button variant="outline" onClick={() => setEditingItemId(null)}>Cancel</Button>
                <Button onClick={handleUpdateItem} disabled={saving}>{saving ? <Loader2 className="h-4 w-4 animate-spin" /> : "Save"}</Button>
              </div>
            </div>
          </DialogContent>
        </Dialog>
      )}
    </div>
  );
}

