452	                        </SelectTrigger>
453	                        <SelectContent>
454	                          <SelectItem value="">Unassign</SelectItem>
455	                          {staff.map((s) => (
456	                            <SelectItem key={s.id} value={String(s.id)}>
457	                              {s.full_name} ({s.email})
458	                            </SelectItem>
459	                          ))}
460	                        </SelectContent>
461	                      </Select>
462	                    </div>
463	                  )}
464	                </div>
465	              ) : (
466	                <div className="space-y-3">
467	                  <p className="text-muted-foreground italic">No staff assigned</p>
468	                  {editMode && (
