471	                      <Select
472	                        value={formData.assigned_staff_id === "" ? "" : String(formData.assigned_staff_id)}
473	                        onValueChange={(v) => handleChange({ target: { name: "assigned_staff_id", value: v } } as any)}
474	                      >
