496	              <CardHeader>
497	                <CardTitle>Service Information</CardTitle>
498	              </CardHeader>
499	              <CardContent className="space-y-4">
500	                {application.service.fields.map((field) => {
501	                  const value = application.application_data?.[field.name];
502	                  const displayValue = value === undefined || value === null || value === ""
503	                    ? <span className="text-muted-foreground italic">Not provided</span>
504	                    : field.field_type === "boolean"
505	                      ? (value ? "Yes" : "No")
506	                      : field.field_type === "date"
507	                        ? new Date(value).toLocaleDateString()
508	                        : String(value);
509	
510	                  return (
511	                    <div key={field.id} className="space-y-1">
512	                      <Label className="text-xs text-muted-foreground">{field.label}</Label>
513	                      {editMode ? (
514	                        <div>
515	                          {field.field_type === "select" && field.options && field.options.length > 0 ? (
516	                            <Select
517	                              value={formData.application_data[field.name] === undefined ? "" : String(formData.application_data[field.name])}
518	                              onValueChange={(v) => handleDynamicFieldChange(field.name, v === "" ? undefined : v)}
519	                            >
520	                              <SelectTrigger>
521	                                <SelectValue placeholder={`Select ${field.label}`} />
522	                              </SelectTrigger>
523	                              <SelectContent>
524	                                <SelectItem value="">Select...</SelectItem>
525	                                {field.options.map((opt) => (
526	                                  <SelectItem key={opt} value={opt}>{opt}</SelectItem>
527	                                ))}
528	                              </SelectContent>
529	                            </Select>
530	                          ) : field.field_type === "boolean" ? (
531	                            <div className="flex items-center gap-2">
532	                              <input
533	                                type="checkbox"
534	                                id={`edit-${field.name}`}
535	                                checked={formData.application_data[field.name] === true}
536	                                onChange={(e) => handleDynamicFieldChange(field.name, e.target.checked)}
537	                                className="h-4 w-4 rounded border-gray-300 text-primary focus:ring-primary"
538	                              />
539	                              <Label htmlFor={`edit-${field.name}`} className="cursor-pointer mb-0">
540	                                {field.label === "Yes" ? "Yes" : "Enabled"}
541	                              </Label>
542	                            </div>
543	                          ) : field.field_type === "textarea" ? (
544	                            <Textarea
545	                              id={`edit-${field.name}`}
546	                              value={formData.application_data[field.name] || ""}
547	                              onChange={(e) => handleDynamicFieldChange(field.name, e.target.value)}
548	                              rows={3}
549	                            />
550	                          ) : field.field_type === "number" ? (
551	                            <Input
552	                              id={`edit-${field.name}`}
553	                              type="number"
554	                              value={formData.application_data[field.name] === undefined ? "" : String(formData.application_data[field.name])}
555	                              onChange={(e) => handleDynamicFieldChange(field.name, e.target.value === "" ? undefined : parseFloat(e.target.value))}
556	                            />
557	                          ) : field.field_type === "date" ? (
558	                            <Input
559	                              id={`edit-${field.name}`}
560	                              type="date"
561	                              value={formData.application_data[field.name] || ""}
562	                              onChange={(e) => handleDynamicFieldChange(field.name, e.target.value || undefined)}
563	                            />
564	                          ) : (
565	                            <Input
566	                              id={`edit-${field.name}`}
567	                              value={formData.application_data[field.name] || ""}
568	                              onChange={(e) => handleDynamicFieldChange(field.name, e.target.value || undefined)}
569	                            />
570	                          )}
571	                        </div>
572	                      ) : (
573	                        <p>{displayValue}</p>
574	                      )}
575	                    </div>
576	                  );
577	                })}
578	              </CardContent>
579	            </Card>
580	          )}
581	
582	          {/* Notes */}
583	          <Card className="md:col-span-2 lg:col-span-3">
584	            <CardHeader>
585	              <CardTitle>Internal Notes</CardTitle>
586	            </CardHeader>
587	            <CardContent>
588	              {editMode ? (
589	                <div className="space-y-2">
590	                  <Label htmlFor="notes">Notes</Label>
591	                  <Textarea
592	                    id="notes"
593	                    value={formData.notes}
594	                    onChange={handleChange}
595	                    rows={4}
596	                    placeholder="Add internal notes..."
597	                  />
598	                </div>
599	              ) : (
600	                <p className={application.notes ? "" : "text-muted-foreground italic"}>
601	                  {application.notes || "No notes added"}
602	                </p>
603	              )}
604	            </CardContent>
605	          </Card>
606	
607	          {/* Metadata */}
608	          <Card className="md:col-span-2 lg:col-span-3">
609	            <CardHeader>
610	              <CardTitle>Application Details</CardTitle>
611	            </CardHeader>
612	            <CardContent className="grid gap-4 sm:grid-cols-2">
613	              <div>
614	                <Label className="text-xs text-muted-foreground">Created</Label>
615	                <p>{new Date(application.created_at).toLocaleString()}</p>
616	              </div>
617	              <div>
618	                <Label className="text-xs text-muted-foreground">Last Updated</Label>
619	                <p>{new Date(application.updated_at).toLocaleString()}</p>
620	              </div>
621	              <div>
622	                <Label className="text-xs text-muted-foreground">Customer ID</Label>
623	                <p className="font-mono">{application.customer_id}</p>
624	              </div>
625	              <div>
626	                <Label className="text-xs text-muted-foreground">Service ID</Label>
627	                <p className="font-mono">{application.service_id}</p>
628	              </div>
629	            </CardContent>
630	          </Card>
631	        </div>
632	
633	        {/* Document Management Section */}
634	        {shopId && application && (
635	          <div className="mt-8">
636	            <DocumentManager
