641	              canReject={true}
642	              canDelete={true}
643	              onChecklistUpdated={fetchApplication}
644	            />
645	          </div>
646	        )}
647	
648	        {editMode && (
649	          <div className="mt-6 flex justify-end gap-3">
650	            <Button variant="outline" onClick={() => {
651	              setFormData({
652	                status: application.status,
653	                assigned_staff_id: application.assigned_staff_id || "",
654	                application_data: application.application_data || {},
655	                notes: application.notes || "",
656	              });
