205	          "Content-Type": "application/json",
206	          "Authorization": `Bearer ${localStorage.getItem("access_token")}`,
207	        },
208	        body: JSON.stringify(payload),
209	      });
210	      if (!resp.ok) {
211	        const data = await resp.json();
212	        throw new Error(data.detail || "Failed to update application");
213	      }
214	      const updated = await resp.json();
215	      setApplication(updated);
216	      setEditMode(false);
217	    } catch (err) {
218	      setError(err instanceof Error ? err.message : "An error occurred");
219	    } finally {
220	      setSaving(false);
221	    }
222	  };
223	
224	  if (authLoading) {
225	    return (
226	      <div className="flex min-h-screen items-center justify-center">
227	        <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-primary" />
228	      </div>
229	    );
230	  }
231	
232	  if (loading) {
233	    return (
234	      <ProtectedRoute>
235	        <div className="container mx-auto py-8">
236	          <div className="flex items-center justify-center h-64">
237	            <Loader2 className="h-8 w-8 animate-spin text-primary" />
238	          </div>
239	        </div>
240	      </ProtectedRoute>
241	    );
242	  }
243	
244	  if (error) {
245	    return (
246	      <ProtectedRoute>
247	        <div className="container mx-auto py-8">
248	          <div className="text-center">
249	            <AlertCircle className="h-12 w-12 text-destructive mx-auto mb-4" />
250	            <h2 className="text-xl font-semibold mb-2">Failed to load application</h2>
251	            <p className="text-muted-foreground mb-4">{error}</p>
252	            <Button variant="outline" asChild>
253	              <Link href="/dashboard/applications">
254	                <ArrowLeft className="mr-2 h-4 w-4" />
255	                Back to Applications
256	              </Link>
257	            </Button>
258	          </div>
259	        </div>
260	      </ProtectedRoute>
261	    );
262	  }
263	
264	  if (!application) {
265	    return (
266	      <ProtectedRoute>
267	        <div className="container mx-auto py-8">
268	          <div className="text-center">
269	            <X className="h-12 w-12 text-destructive mx-auto mb-4" />
270	            <h2 className="text-xl font-semibold mb-2">Application not found</h2>
271	            <Button variant="outline" asChild>
272	              <Link href="/dashboard/applications">
273	                <ArrowLeft className="mr-2 h-4 w-4" />
274	                Back to Applications
275	              </Link>
276	            </Button>
277	          </div>
278	        </div>
279	      </ProtectedRoute>
280	    );
281	  }
282	
283	  const statusOrder: ApplicationStatus[] = ["enquiry", "applied", "documents_pending", "under_processing", "completed", "rejected", "cancelled"];
284	  const currentStatusIndex = statusOrder.indexOf(application.status);
285	
286	  return (
287	    <ProtectedRoute>
288	      <div className="container mx-auto py-8">
289	        <div className="flex items-center gap-4 mb-6">
290	          <Button variant="outline" size="icon" asChild>
291	            <Link href={`/dashboard/applications?shop_id=${shopId}`}>
292	              <ArrowLeft className="h-4 w-4" />
293	            </Link>
294	          </Button>
295	          <div className="flex-1">
296	            <h1 className="text-3xl font-bold tracking-tight">{application.application_number}</h1>
297	            <p className="text-muted-foreground mt-1">{application.service.name}</p>
298	          </div>
299	          <div className="flex items-center gap-2">
300	            {getStatusBadge(application.status)}
301	            <Button variant="outline" onClick={() => setEditMode(!editMode)}>
302	              {editMode ? <X className="h-4 w-4" /> : <Edit className="h-4 w-4" />}
303	              {editMode ? "Cancel" : "Edit"}
304	            </Button>
305	          </div>
306	        </div>
307	
308	        {error && (
309	          <div className="mb-6 p-4 rounded-lg bg-destructive/10 text-destructive">
310	            {error}
311	          </div>
312	        )}
313	
314	        {/* Status Timeline */}
315	        <Card className="mb-6">
316	          <CardHeader>
317	            <CardTitle>Status Timeline</CardTitle>
318	            <CardDescription>Track the progress of this application</CardDescription>
319	          </CardHeader>
320	          <CardContent>
321	            <div className="relative pl-4">
322	              <div className="absolute left-2 top-0 bottom-0 w-0.5 bg-muted" />
323	              {statusOrder.map((status, index) => {
324	                const isCompleted = index < currentStatusIndex;
325	                const isCurrent = index === currentStatusIndex;
326	                const isFuture = index > currentStatusIndex;
327	
328	                const statusConfigs: Record<ApplicationStatus, { label: string; icon: React.ReactNode }> = {
329	                  enquiry: { label: "Enquiry", icon: <span className="text-xs">1</span> },
330	                  applied: { label: "Applied", icon: <CheckCircle className="h-4 w-4" /> },
331	                  documents_pending: { label: "Documents Pending", icon: <AlertCircle className="h-4 w-4" /> },
332	                  under_processing: { label: "Under Processing", icon: <Loader2 className="h-4 w-4 animate-spin" /> },
333	                  completed: { label: "Completed", icon: <CheckCircle className="h-4 w-4 text-green-500" /> },
334	                  rejected: { label: "Rejected", icon: <X className="h-4 w-4 text-red-500" /> },
335	                  cancelled: { label: "Cancelled", icon: <X className="h-4 w-4 text-gray-500" /> },
336	                };
337	                const config = statusConfigs[status];
338	
339	                return (
340	                  <div key={status} className="relative flex items-start gap-4 pb-6 last:pb-0">
341	                    <div className={`flex h-8 w-8 items-center justify-center rounded-full border-2 shrink-0 relative z-10 ${
342	                      isCompleted ? "bg-primary border-primary text-primary-foreground" :
343	                      isCurrent ? "bg-primary border-primary text-primary-foreground" :
344	                      "bg-background border-muted text-muted-foreground"
345	                    }`}>
346	                      {isCompleted ? <CheckCircle className="h-4 w-4" /> : config.icon}
347	                    </div>
348	                    <div className="flex-1 pt-1">
349	                      <p className={`font-medium ${isCurrent ? "text-foreground" : isCompleted ? "text-foreground" : "text-muted-foreground"}`}>
350	                        {config.label}
351	                      </p>
352	                      <p className="text-sm text-muted-foreground">
353	                        {isCompleted && application.updated_at && `Updated ${new Date(application.updated_at).toLocaleDateString()}`}
354	                      </p>
355	                    </div>
356	                  </div>
357	                );
358	              })}
359	            </div>
360	          </CardContent>
361	        </Card>
362	
363	        <div className="grid gap-6 md:grid-cols-2 lg:grid-cols-3">
364	          {/* Customer Info */}
365	          <Card>
366	            <CardHeader>
367	              <CardTitle className="flex items-center gap-2">
368	                <Users className="h-5 w-5" />
369	                Customer
370	              </CardTitle>
371	            </CardHeader>
372	            <CardContent className="space-y-3">
373	              <div>
374	                <Label className="text-xs text-muted-foreground">Name</Label>
375	                <p className="font-medium">{application.customer.name}</p>
376	              </div>
377	              <div>
378	                <Label className="text-xs text-muted-foreground">Mobile</Label>
379	                <p className="font-mono">{application.customer.mobile}</p>
380	              </div>
381	              {application.customer.email && (
382	                <div>
383	                  <Label className="text-xs text-muted-foreground">Email</Label>
384	                  <p>{application.customer.email}</p>
385	                </div>
386	              )}
387	              {application.customer.address && (
388	                <div>
389	                  <Label className="text-xs text-muted-foreground">Address</Label>
390	                  <p className="text-sm">{application.customer.address}</p>
391	                </div>
392	              )}
393	              <div className="pt-2 border-t">
394	                <Button variant="outline" size="sm" asChild>
395	                  <Link href={`/dashboard/customers/${application.customer.id}?shop_id=${shopId}`}>
396	                    View Customer Profile
397	                  </Link>
398	                </Button>
399	              </div>
400	            </CardContent>
401	          </Card>
402	
403	          {/* Service Info */}
404	          <Card>
405	            <CardHeader>
406	              <CardTitle className="flex items-center gap-2">
407	                <Banknote className="h-5 w-5" />
408	                Service
409	              </CardTitle>
410	            </CardHeader>
411	            <CardContent className="space-y-3">
412	              <div>
413	                <Label className="text-xs text-muted-foreground">Name</Label>
414	                <p className="font-medium">{application.service.name}</p>
415	              </div>
416	              {application.service.description && (
417	                <div>
418	                  <Label className="text-xs text-muted-foreground">Description</Label>
419	                  <p className="text-sm">{application.service.description}</p>
420	                </div>
421	              )}
422	              <div>
423	                <Label className="text-xs text-muted-foreground">Base Price</Label>
424	                <p className="font-mono">{new Intl.NumberFormat("en-US", { style: "currency", currency: "USD" }).format(application.service.base_price)}</p>
425	              </div>
426	              <div className="pt-2 border-t">
427	                <Button variant="outline" size="sm" asChild>
428	                  <Link href={`/dashboard/services/${application.service.id}?shop_id=${shopId}`}>
429	                    View Service Details
430	                  </Link>
431	                </Button>
432	              </div>
433	            </CardContent>
434	          </Card>
435	
436	          {/* Assigned Staff */}
437	          <Card>
438	            <CardHeader>
439	              <CardTitle className="flex items-center gap-2">
440	                <Users className="h-5 w-5" />
441	                Assigned Staff
442	              </CardTitle>
443	            </CardHeader>
444	            <CardContent>
445	              {application.assigned_staff ? (
446	                <div className="space-y-3">
447	                  <div className="flex items-center gap-3">
448	                    <div className="flex-shrink-0 h-10 w-10 rounded bg-muted/50 flex items-center justify-center">
449	                      <Users className="h-5 w-5 text-muted-foreground" />
450	                    </div>
451	                    <div>
452	                      <p className="font-medium">{application.assigned_staff.full_name}</p>
453	                      <p className="text-sm text-muted-foreground">{application.assigned_staff.email}</p>
454	                    </div>
455	                  </div>
456	                  {editMode && (
457	                    <div className="space-y-2">
458	                      <Label htmlFor="assigned_staff_id">Reassign Staff</Label>
459	                      <Select
460	                        value={formData.assigned_staff_id === "" ? "" : String(formData.assigned_staff_id)}
461	                        onValueChange={(v) => handleChange({ target: { name: "assigned_staff_id", value: v } } as any)}
462	                      >
463	                        <SelectTrigger>
464	                          <SelectValue placeholder="Select staff member" />
465	                        </SelectTrigger>
466	                        <SelectContent>
467	                          <SelectItem value="">Unassign</SelectItem>
468	                          {staff.map((s) => (
469	                            <SelectItem key={s.id} value={String(s.id)}>
470	                              {s.full_name} ({s.email})
471	                            </SelectItem>
472	                          ))}
473	                        </SelectContent>
474	                      </Select>
475	                    </div>
476	                  )}
477	                </div>
478	              ) : (
479	                <div className="space-y-3">
480	                  <p className="text-muted-foreground italic">No staff assigned</p>
481	                  {editMode && (
482	                    <div className="space-y-2">
483	                      <Label htmlFor="assigned_staff_id">Assign Staff</Label>
484	                      <Select
485	                        value={formData.assigned_staff_id === "" ? "" : String(formData.assigned_staff_id)}
486	                        onValueChange={(v) => handleChange({ target: { name: "assigned_staff_id", value: v } } as any)}
487	                      >
488	                        <SelectTrigger>
489	                          <SelectValue placeholder="Select staff member" />
490	                        </SelectTrigger>
491	                        <SelectContent>
492	                          {staff.map((s) => (
493	                            <SelectItem key={s.id} value={String(s.id)}>
494	                              {s.full_name} ({s.email})
495	                            </SelectItem>
496	                          ))}
497	                        </SelectContent>
498	                      </Select>
499	                    </div>
500	                  )}
501	                </div>
502	              )}
503	            </CardContent>
504	          </Card>
505	
506	          {/* Application Data */}
507	          {application.service.fields && application.service.fields.length > 0 && (
508	            <Card className="md:col-span-2 lg:col-span-3">
509	              <CardHeader>
510	                <CardTitle>Service Information</CardTitle>
511	              </CardHeader>
512	              <CardContent className="space-y-4">
513	                {application.service.fields.map((field) => {
514	                  const value = application.application_data?.[field.name];
515	                  const displayValue = value === undefined || value === null || value === ""
516	                    ? <span className="text-muted-foreground italic">Not provided</span>
517	                    : field.field_type === "boolean"
518	                      ? (value ? "Yes" : "No")
519	                      : field.field_type === "date"
520	                        ? new Date(value).toLocaleDateString()
521	                        : String(value);
522	
523	                  return (
524	                    <div key={field.id} className="space-y-1">
525	                      <Label className="text-xs text-muted-foreground">{field.label}</Label>
526	                      {editMode ? (
527	                        <div>
528	                          {field.field_type === "select" && field.options && field.options.length > 0 ? (
529	                            <Select
530	                              value={formData.application_data[field.name] === undefined ? "" : String(formData.application_data[field.name])}
531	                              onValueChange={(v) => handleDynamicFieldChange(field.name, v === "" ? undefined : v)}
532	                            >
533	                              <SelectTrigger>
534	                                <SelectValue placeholder={`Select ${field.label}`} />
535	                              </SelectTrigger>
536	                              <SelectContent>
537	                                <SelectItem value="">Select...</SelectItem>
538	                                {field.options.map((opt) => (
539	                                  <SelectItem key={opt} value={opt}>{opt}</SelectItem>
540	                                ))}
541	                              </SelectContent>
542	                            </Select>
543	                          ) : field.field_type === "boolean" ? (
544	                            <div className="flex items-center gap-2">
545	                              <input
546	                                type="checkbox"
547	                                id={`edit-${field.name}`}
548	                                checked={formData.application_data[field.name] === true}
549	                                onChange={(e) => handleDynamicFieldChange(field.name, e.target.checked)}
550	                                className="h-4 w-4 rounded border-gray-300 text-primary focus:ring-primary"
551	                              />
552	                              <Label htmlFor={`edit-${field.name}`} className="cursor-pointer mb-0">
553	                                {field.label === "Yes" ? "Yes" : "Enabled"}
554	                              </Label>
555	                            </div>
556	                          ) : field.field_type === "textarea" ? (
557	                            <Textarea
558	                              id={`edit-${field.name}`}
559	                              value={formData.application_data[field.name] || ""}
560	                              onChange={(e) => handleDynamicFieldChange(field.name, e.target.value)}
561	                              rows={3}
562	                            />
563	                          ) : field.field_type === "number" ? (
564	                            <Input
565	                              id={`edit-${field.name}`}
566	                              type="number"
567	                              value={formData.application_data[field.name] === undefined ? "" : String(formData.application_data[field.name])}
568	                              onChange={(e) => handleDynamicFieldChange(field.name, e.target.value === "" ? undefined : parseFloat(e.target.value))}
569	                            />
570	                          ) : field.field_type === "date" ? (
571	                            <Input
572	                              id={`edit-${field.name}`}
573	                              type="date"
574	                              value={formData.application_data[field.name] || ""}
575	                              onChange={(e) => handleDynamicFieldChange(field.name, e.target.value || undefined)}
576	                            />
577	                          ) : (
578	                            <Input
579	                              id={`edit-${field.name}`}
580	                              value={formData.application_data[field.name] || ""}
581	                              onChange={(e) => handleDynamicFieldChange(field.name, e.target.value || undefined)}
582	                            />
583	                          )}
584	                        </div>
585	                      ) : (
586	                        <p>{displayValue}</p>
587	                      )}
588	                    </div>
589	                  );
590	                })}
591	              </CardContent>
592	            </Card>
593	          )}
594	
595	          {/* Notes */}
596	          <Card className="md:col-span-2 lg:col-span-3">
597	            <CardHeader>
598	              <CardTitle>Internal Notes</CardTitle>
599	            </CardHeader>
600	            <CardContent>
601	              {editMode ? (
602	                <div className="space-y-2">
603	                  <Label htmlFor="notes">Notes</Label>
604	                  <Textarea
605	                    id="notes"
606	                    value={formData.notes}
607	                    onChange={handleChange}
608	                    rows={4}
609	                    placeholder="Add internal notes..."
610	                  />
611	                </div>
612	              ) : (
613	                <p className={application.notes ? "" : "text-muted-foreground italic"}>
614	                  {application.notes || "No notes added"}
615	                </p>
616	              )}
617	            </CardContent>
618	          </Card>
619	
620	          {/* Metadata */}
621	          <Card className="md:col-span-2 lg:col-span-3">
622	            <CardHeader>
623	              <CardTitle>Application Details</CardTitle>
624	            </CardHeader>
625	            <CardContent className="grid gap-4 sm:grid-cols-2">
626	              <div>
627	                <Label className="text-xs text-muted-foreground">Created</Label>
628	                <p>{new Date(application.created_at).toLocaleString()}</p>
629	              </div>
630	              <div>
631	                <Label className="text-xs text-muted-foreground">Last Updated</Label>
632	                <p>{new Date(application.updated_at).toLocaleString()}</p>
633	              </div>
634	              <div>
635	                <Label className="text-xs text-muted-foreground">Customer ID</Label>
636	                <p className="font-mono">{application.customer_id}</p>
637	              </div>
638	              <div>
639	                <Label className="text-xs text-muted-foreground">Service ID</Label>
640	                <p className="font-mono">{application.service_id}</p>
641	              </div>
642	            </CardContent>
643	          </Card>
644	        </div>
645	
646	        {/* Document Management Section */}
647	        {shopId && application && (
648	          <div className="mt-8">
649	            <DocumentManager
650	              shopId={shopId}
651	              applicationId={application.id}
652	              canUpload={true}
653	              canVerify={true}
654	              canReject={true}
655	              canDelete={true}
656	              onChecklistUpdated={fetchApplication}
657	            />
658	          </div>
659	        )}
660	
661	        {editMode && (
662	          <div className="mt-6 flex justify-end gap-3">
663	            <Button variant="outline" onClick={() => {
664	              setFormData({
665	                status: application.status,
666	                assigned_staff_id: application.assigned_staff_id || "",
667	                application_data: application.application_data || {},
668	                notes: application.notes || "",
669	              });
670	              setEditMode(false);
671	            }}>
672	              Cancel
673	            </Button>
674	            <Button onClick={handleSave} disabled={saving}>
