566	                              onValueChange={(v) => handleDynamicFieldChange(field.name, v === "" ? undefined : v)}
567	                            >
568	                              <SelectTrigger>
569	                                <SelectValue placeholder={`Select ${field.label}`} />
570	                              </SelectTrigger>
571	                              <SelectContent>
572	                                <SelectItem value="">Select...</SelectItem>
573	                                {field.options.map((opt) => (
574	                                  <SelectItem key={opt} value={opt}>{opt}</SelectItem>
575	                                ))}
576	                              </SelectContent>
577	                            </Select>
578	                          ) : field.field_type === "boolean" ? (
579	                            <div className="flex items-center gap-2">
580	                              <input
581	                                type="checkbox"
582	                                id={`edit-${field.name}`}
583	                                checked={formData.application_data[field.name] === true}
584	                                onChange={(e) => handleDynamicFieldChange(field.name, e.target.checked)}
585	                                className="h-4 w-4 rounded border-gray-300 text-primary focus:ring-primary"
586	                              />
587	                              <Label htmlFor={`edit-${field.name}`} className="cursor-pointer mb-0">
588	                                {field.label === "Yes" ? "Yes" : "Enabled"}
589	                              </Label>
590	                            </div>
591	                          ) : field.field_type === "textarea" ? (
592	                            <Textarea
593	                              id={`edit-${field.name}`}
594	                              value={formData.application_data[field.name] || ""}
595	                              onChange={(e) => handleDynamicFieldChange(field.name, e.target.value)}
596	                              rows={3}
597	                            />
598	                          ) : field.field_type === "number" ? (
599	                            <Input
600	                              id={`edit-${field.name}`}
601	                              type="number"
602	                              value={formData.application_data[field.name] === undefined ? "" : String(formData.application_data[field.name])}
603	                              onChange={(e) => handleDynamicFieldChange(field.name, e.target.value === "" ? undefined : parseFloat(e.target.value))}
604	                            />
605	                          ) : field.field_type === "date" ? (
606	                            <Input
607	                              id={`edit-${field.name}`}
608	                              type="date"
609	                              value={formData.application_data[field.name] || ""}
610	                              onChange={(e) => handleDynamicFieldChange(field.name, e.target.value || undefined)}
611	                            />
612	                          ) : (
613	                            <Input
614	                              id={`edit-${field.name}`}
615	                              value={formData.application_data[field.name] || ""}
616	                              onChange={(e) => handleDynamicFieldChange(field.name, e.target.value || undefined)}
617	                            />
618	                          )}
619	                        </div>
620	                      ) : (
621	                        <p>{displayValue}</p>
622	                      )}
623	                    </div>
624	                  );
625	                })}
626	              </CardContent>
627	            </Card>
628	          )}
629	
630	          {/* Notes */}
631	          <Card className="md:col-span-2 lg:col-span-3">
632	            <CardHeader>
633	              <CardTitle>Internal Notes</CardTitle>
634	            </CardHeader>
635	            <CardContent>
636	              {editMode ? (
637	                <div className="space-y-2">
638	                  <Label htmlFor="notes">Notes</Label>
639	                  <Textarea
640	                    id="notes"
641	                    value={formData.notes}
642	                    onChange={handleChange}
643	                    rows={4}
644	                    placeholder="Add internal notes..."
645	                  />
646	                </div>
647	              ) : (
648	                <p className={application.notes ? "" : "text-muted-foreground italic"}>
649	                  {application.notes || "No notes added"}
650	                </p>
651	              )}
652	            </CardContent>
653	          </Card>
654	
655	          {/* Metadata */}
656	          <Card className="md:col-span-2 lg:col-span-3">
657	            <CardHeader>
658	              <CardTitle>Application Details</CardTitle>
659	            </CardHeader>
660	            <CardContent className="grid gap-4 sm:grid-cols-2">
661	              <div>
662	                <Label className="text-xs text-muted-foreground">Created</Label>
663	                <p>{new Date(application.created_at).toLocaleString()}</p>
664	              </div>
665	              <div>
666	                <Label className="text-xs text-muted-foreground">Last Updated</Label>
667	                <p>{new Date(application.updated_at).toLocaleString()}</p>
668	              </div>
669	              <div>
670	                <Label className="text-xs text-muted-foreground">Customer ID</Label>
671	                <p className="font-mono">{application.customer_id}</p>
672	              </div>
673	              <div>
674	                <Label className="text-xs text-muted-foreground">Service ID</Label>
675	                <p className="font-mono">{application.service_id}</p>
676	              </div>
677	            </CardContent>
678	          </Card>
679	        </div>
680	
681	        {/* Document Management Section */}
682	        {shopId && application && (
683	          <div className="mt-8">
684	            <DocumentManager
685	              shopId={shopId}
686	              applicationId={application.id}
687	              canUpload={true}
688	              canVerify={true}
689	              canReject={true}
690	              canDelete={true}
691	              onChecklistUpdated={fetchApplication}
692	            />
693	          </div>
694	        )}
695	
696	        {editMode && (
697	          <div className="mt-6 flex justify-end gap-3">
698	            <Button variant="outline" onClick={() => {
699	              setFormData({
700	                status: application.status,
701	                assigned_staff_id: application.assigned_staff_id || "",
702	                application_data: application.application_data || {},
703	                notes: application.notes || "",
704	              });
705	              setEditMode(false);
706	            }}>
707	              Cancel
708	            </Button>
709	            <Button onClick={handleSave} disabled={saving}>
710	              <Save className="mr-2 h-4 w-4" />
711	              {saving ? "Saving..." : "Save Changes"}
712	            </Button>
713	          </div>
714	        )}
715	      </div>
716	    </ProtectedRoute>
717	  );
718	}
719	
720	export default function ApplicationDetailPage() {
721	  return <ApplicationDetailContent />;
722	}

