2	
3	import { useState, useEffect, useCallback } from "react";
4	import { Button } from "@/components/ui/button";
5	import { Input } from "@/components/ui/input";
6	import { Label } from "@/components/ui/label";
7	import { Textarea } from "@/components/ui/textarea";
8	import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
9	import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
10	import { Badge } from "@/components/ui/badge";
11	import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/components/ui/table";
12	import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogTrigger } from "@/components/ui/dialog";
13	import { Separator } from "@/components/ui/separator";
14	import { formatCurrency } from "@/lib/utils";
15	import {
16	  Plus, Edit, Trash2, Save, X, Eye, Receipt, DollarSign,
17	  Minus, AlertCircle, CheckCircle, Loader2, CreditCard, Banknote,
18	  ArrowLeft, ArrowRight, RefreshCw, FileText, Shield, AlertTriangle,
19	  ChevronDown, ChevronUp
20	} from "lucide-react";
21	import {
22	  BillingResponse,
23	  BillingItemResponse,
24	  PaymentResponse,
25	  BillingItemCreate,
26	  BillingItemUpdate,
27	  PaymentCreate,
28	  PaymentFormData,
29	  PaymentMethod,
30	  BillingStatus,
31	  PaymentStatus,
32	  BillingFormData,
33	  PAYMENT_METHOD_LABELS,
34	  PAYMENT_STATUS_LABELS,
35	  BILLING_STATUS_LABELS,
36	  DISCOUNT_TYPE_LABELS,
37	  DiscountType,
38	  BillingCalculationPreview,
39	} from "@/src/types/billing";
40	
41	interface BillingManagerProps {
42	  shopId: number;
43	  applicationId: number;
44	  applicationNumber: string;
45	  serviceName: string;
46	  serviceBasePrice: number;
47	  customerName: string;
48	  canCreate: boolean;
49	  canUpdate: boolean;
50	  canDiscount: boolean;
51	  canCharge: boolean;
52	  canVoid: boolean;
53	  canPaymentCreate: boolean;
54	  canPaymentView: boolean;
55	  onBillingCreated?: () => void;
56	}
57	
58	export function BillingManager({
59	  shopId,
60	  applicationId,
61	  applicationNumber,
62	  serviceName,
63	  serviceBasePrice,
64	  customerName,
65	  canCreate,
66	  canUpdate,
67	  canDiscount,
68	  canCharge,
69	  canVoid,
70	  canPaymentCreate,
71	  canPaymentView,
72	  onBillingCreated,
73	}: BillingManagerProps) {
74	  const [loading, setLoading] = useState(true);
75	  const [error, setError] = useState<string | null>(null);
76	  const [billing, setBilling] = useState<BillingResponse | null>(null);
77	  const [payments, setPayments] = useState<PaymentResponse[]>([]);
78	  const [saving, setSaving] = useState(false);
79	  const [creating, setCreating] = useState(false);
80	  const [creatingPayment, setCreatingPayment] = useState(false);
81	  const [showCreateDialog, setShowCreateDialog] = useState(false);
82	  const [showEditDialog, setShowEditDialog] = useState(false);
83	  const [showPaymentDialog, setShowPaymentDialog] = useState(false);
84	  const [showPreviewDialog, setShowPreviewDialog] = useState(false);
85	  const [editingItemId, setEditingItemId] = useState<number | null>(null);
86	  const [previewData, setPreviewData] = useState<BillingCalculationPreview | null>(null);
87	
88	  // Form states
89	  const [createForm, setCreateForm] = useState<BillingFormData>({
90	    items: [
91	      {
92	        name: serviceName,
93	        description: `Service: ${serviceName}`,
94	        amount: serviceBasePrice,
95	        is_service_item: true,
96	        service_id: undefined,
97	        sort_order: 0,
98	      },
99	    ],
100	    discount_type: undefined,
101	    discount_value: undefined,
102	    discount_reason: "",
103	    notes: "",
104	  });
105	
106	  const [editForm, setEditForm] = useState<Partial<BillingFormData>>({});
107	
108	  const [itemForm, setItemForm] = useState<BillingItemCreate>({
109	    name: "",
110	    description: "",
111	    amount: 0,
112	    is_service_item: false,
113	    service_id: undefined,
114	    sort_order: 0,
115	  });
116	
117	  const [paymentForm, setPaymentForm] = useState<PaymentFormData>({
118	    amount: 0,
119	    payment_method: "cash",
120	    reference_number: "",
121	    reference_exception: false,
122	    reference_exception_reason: "",
123	    notes: "",
124	  });
125	
126	  const isDigitalPayment = (method: PaymentMethod) =>
127	    method !== "cash";
128	
129	  const requiresReference = (method: PaymentMethod) =>
130	    isDigitalPayment(method);
131	
132	  const fetchBilling = useCallback(async () => {
133	    setLoading(true);
134	    try {
135	      const response = await fetch(`/api/v1/shops/${shopId}/applications/${applicationId}/billing`, {
136	        headers: { "Authorization": `Bearer ${localStorage.getItem("access_token")}` },
137	      });
138	      if (response.ok) {
139	        const data = await response.json();
140	        setBilling(data);
141	      } else if (response.status === 404) {
142	        setBilling(null);
143	      } else {
144	        throw new Error("Failed to fetch billing");
145	      }
146	    } catch (err) {
147	      setError(err instanceof Error ? err.message : "An error occurred");
148	    } finally {
149	      setLoading(false);
150	    }
151	  }, [shopId, applicationId]);
152	
153	  const fetchPayments = useCallback(async () => {
154	    if (!billing) return;
155	    try {
156	      const response = await fetch(`/api/v1/shops/${shopId}/applications/billing/${billing.id}/payments`, {
157	        headers: { "Authorization": `Bearer ${localStorage.getItem("access_token")}` },
158	      });
159	      if (response.ok) {
160	        const data = await response.json();
161	        setPayments(data.items || data);
162	      }
163	    } catch (err) {
164	      console.error("Failed to fetch payments:", err);
165	    }
166	  }, [shopId, billing]);
167	
168	  useEffect(() => {
169	    fetchBilling();
170	  }, [fetchBilling]);
171	
172	  useEffect(() => {
173	    fetchPayments();
174	  }, [fetchPayments]);
175	
176	  const handlePreviewCalculation = async () => {
177	    if (createForm.items.length === 0) return;
178	    try {
179	      const response = await fetch(`/api/v1/shops/${shopId}/applications/billing/preview`, {
180	        method: "POST",
181	        headers: {
182	          "Content-Type": "application/json",
183	          "Authorization": `Bearer ${localStorage.getItem("access_token")}`,
184	        },
185	        body: JSON.stringify({
186	          items: createForm.items,
187	          discount_type: createForm.discount_type,
188	          discount_value: createForm.discount_value,
189	        }),
190	      });
191	      if (response.ok) {
192	        const data = await response.json();
193	        setPreviewData(data);
194	        setShowPreviewDialog(true);
195	      }
196	    } catch (err) {
197	      console.error("Failed to preview calculation:", err);
198	    }
199	  };
200	
201	  const handleCreateBilling = async () => {
202	    if (createForm.items.length === 0) {
203	      setError("At least one line item is required");
204	      return;
205	    }
206	    if (createForm.discount_type && createForm.discount_value && !createForm.discount_reason) {
207	      setError("Discount reason is required");
208	      return;
209	    }
210	    setCreating(true);
211	    setError(null);
212	    try {
213	      const response = await fetch(`/api/v1/shops/${shopId}/applications/${applicationId}/billing`, {
214	        method: "POST",
215	        headers: {
216	          "Content-Type": "application/json",
217	          "Authorization": `Bearer ${localStorage.getItem("access_token")}`,
218	        },
219	        body: JSON.stringify({
220	          application_id: applicationId,
221	          ...createForm,
222	        }),
223	      });
224	      if (response.ok) {
225	        const data = await response.json();
226	        setBilling(data);
227	        setShowCreateDialog(false);
228	        onBillingCreated?.();
229	      } else {
230	        const data = await response.json();
231	        throw new Error(data.detail || "Failed to create billing");
