806	              <Table>
807	                <TableHeader>
808	                  <TableRow>
809	                    <TableHead>Item</TableHead>
810	                    <TableHead className="text-right">Amount</TableHead>
811	                    <TableHead className="text-center">Type</TableHead>
812	                    {billing.billing_status === "draft" && billing.amount_paid === 0 && canCharge && <TableHead className="text-center">Actions</TableHead>}
813	                  </TableRow>
814	                </TableHeader>
815	                <TableBody>
816	                  {billing.items.map((item) => (
817	                    <TableRow key={item.id}>
818	                      <TableCell>
819	                        <div>
820	                          <p className="font-medium">{item.name}</p>
821	                          {item.description && <p className="text-sm text-muted-foreground">{item.description}</p>}
822	                        </div>
823	                      </TableCell>
824	                      <TableCell className="font-mono text-right">{formatCurrency(item.amount)}</TableCell>
825	                      <TableCell className="text-center">
826	                        <Badge variant={item.is_service_item ? "secondary" : "outline"}>
827	                          {item.is_service_item ? "Service" : "Charge"}
828	                        </Badge>
829	                      </TableCell>
830	                      {billing.billing_status === "draft" && billing.amount_paid === 0 && canCharge && (
831	                        <TableCell className="text-center">
832	                          <div className="flex items-center justify-center gap-1">
833	                            <Button variant="ghost" size="icon" onClick={() => startEditItem(item)}><Edit className="h-4 w-4" /></Button>
834	                            <Button variant="ghost" size="icon" onClick={() => handleDeleteItem(item.id)}><Trash2 className="h-4 w-4 text-destructive" /></Button>
835	                          </div>
836	                        </TableCell>
837	                      )}
838	                    </TableRow>
839	                  ))}
840	                </TableBody>
841	              </Table>
842	            </div>
843	          </div>
844	
845	          {/* Discount Display */}
846	          {billing.discount_amount > 0 && (
847	            <div className="bg-green-50 border border-green-200 rounded-lg p-4">
848	              <div className="flex items-center justify-between">
849	                <div className="flex items-center gap-2">
850	                  <AlertCircle className="h-5 w-5 text-green-600" />
851	                  <div>
852	                    <p className="font-medium">Discount Applied</p>
853	                    <p className="text-sm text-green-700">
854	                      {DISCOUNT_TYPE_LABELS[billing.discount_type as DiscountType] || billing.discount_type}: {billing.discount_value}
855	                      {billing.discount_type === "percentage" ? "%" : formatCurrency(billing.discount_value || 0)}
856	                    </p>
857	                  </div>
858	                </div>
859	                <div className="font-mono text-green-600">-{formatCurrency(billing.discount_amount)}</div>
860	              </div>
861	              {billing.discount_reason && (
862	                <p className="mt-2 text-sm text-green-700"><strong>Reason:</strong> {billing.discount_reason}</p>
863	              )}
864	            </div>
865	          )}
866	
867	          {/* Notes */}
868	          {billing.notes && (
869	            <div className="bg-muted/50 rounded-lg p-4">
870	              <Label className="text-xs text-muted-foreground">Notes</Label>
871	              <p>{billing.notes}</p>
872	            </div>
873	          )}
