877	            {canUpdate && billing.billing_status === "draft" && billing.amount_paid === 0 && (
878	              <Button variant="outline" onClick={() => {
879	                setEditForm({
880	                  notes: billing.notes,
881	                  discount_type: billing.discount_type,
882	                  discount_value: billing.discount_value,
883	                  discount_reason: billing.discount_reason,
884	                });
885	                setShowEditDialog(true);
886	              }}>
887	                <Edit className="h-4 w-4 mr-1" /> Edit Details
888	              </Button>
889	            )}
890	            {canVoid && billing.billing_status !== "void" && billing.amount_paid === 0 && (
891	              <Button variant="destructive" onClick={handleVoidBilling} disabled={saving}>
892	                <Shield className="h-4 w-4 mr-1" /> Void Billing
893	              </Button>
894	            )}
895	            {billing.billing_status === "draft" && (
896	              <Button variant="secondary" onClick={handleIssueBilling} disabled={saving}>
897	                <FileText className="h-4 w-4 mr-1" /> Issue Billing
898	              </Button>
